insert into public.catalogo_infracciones
  (numero, descripcion, texto, articulo, fraccion, inciso, cuotas_min, cuotas_max, grave, tipo_rapido)
values
(1, 'Circular con placas vencidas', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Placas de circulación vigentes, expedidas por la autoridad competente; (circular con placas vencidas).', '19', 'I', '', 5, 10, false, null),
(2, 'Circular sin placas', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Placas de circulación vigentes, expedidas por la autoridad competente; (circular sin placas).', '19', 'I', '', 30, 50, false, null),
(3, 'Permiso provisional vigente, sólo en el caso de no portar placas de circulación los vehículos de uso particular; únicamente cuando este sea expedido en otra Entidad Federativa…', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Permiso provisional vigente, sólo en el caso de no portar placas de circulación los vehículos de uso particular; únicamente cuando este sea expedido en otra Entidad Federativa o en el extranjero;', '19', 'II', '', 10, 15, false, null),
(4, 'No portar tarjeta de circulación vigente', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Tarjeta de circulación vigente original. En su caso la copia cotejada vigente de la tarjeta de circulación emitida por la autoridad competente, será equivalente al original;', '19', 'III', '', 10, 15, false, 'No portar documentos'),
(5, 'Calcomanía de placas y refrendo vigente', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Calcomanía de placas y refrendo vigente.', '19', 'IV', '', 2, 4, false, null),
(6, 'Queda prohibido colocar a los vehículos dispositivos u objetos que se asemejen a placas de circulación nacionales o extranjeras, salvo los vehículos autorizados por la…', 'Queda prohibido colocar a los vehículos dispositivos u objetos que se asemejen a placas de circulación nacionales o extranjeras, salvo los vehículos autorizados por la autoridad competente. Las placas deberán ser colocadas en los vehículos autorizados, y serán las que expidan las autoridades correspondientes; en caso de falsificación de placas de circulación, el vehículo que las porte será retirado de la circulación dando vista de lo anterior a la autoridad competente.', '20', '', '', 15, 20, false, null),
(7, 'Circular con placas en lugar indebido', 'Las placas deberán conservarse siempre limpias, sin alteraciones, ni mutilaciones, debiendo colocarse una en la parte frontal exterior del vehículo en el área provista por el fabricante, y la otra en la parte posterior exterior del vehículo. Ambas placas deberán estar siempre visibles para que su lectura sea clara y sin confusión, debiendo estar fijas al vehículo. En caso de no existir un área provista por el fabricante para la colocación de la placa, ésta se colocará en el área central de la defensa posterior y frontal exterior, según sea el caso. (circular con placas en lugar indebido).', '22', 'primer párrafo', '', 7, 15, false, null),
(8, 'Falta de visibilidad en placas', 'Las placas deberán conservarse siempre limpias, sin alteraciones, ni mutilaciones, debiendo colocarse una en la parte frontal exterior del vehículo en el área provista por el fabricante, y la otra en la parte posterior exterior del vehículo. Ambas placas deberán estar siempre visibles para que su lectura sea clara y sin confusión, debiendo estar fijas al vehículo. En caso de no existir un área provista por el fabricante para la colocación de la placa, ésta se colocará en el área central de la defensa posterior y frontal exterior, según sea el caso. (falta de visibilidad en placas).', '22', 'primer párrafo', '', 10, 15, false, null),
(9, 'Instalar o utilizar micas, antirradares o detectores de radares en los vehículos', 'Además, deberán mantenerse en buen estado de conservación y libres de objetos distintivos, de rótulos, micas obscuras, sistemas anti-radares o detector de dispositivos tecnológicos, dobleces, porta placas luminosas, opaco o cualquier alteración que dificulte o impida su legibilidad. (instalar o utilizar micas, antirradares o detectores de radares en los vehículos).', '22', 'segundo párrafo', '', 30, 40, false, null),
(10, 'Queda prohibido el uso de placas en vehículos diferentes para los que fueron expedidas. Para el caso en que se detecten las placas en vehículos distintos a los registrados, se…', 'Queda prohibido el uso de placas en vehículos diferentes para los que fueron expedidas. Para el caso en que se detecten las placas en vehículos distintos a los registrados, se procederá a recoger y retener los documentos, así como el vehículo, dando vista a la autoridad competente.', '26', '', '', 30, 40, false, null),
(11, 'Cambio de propietario; Cambio de domicilio; Cambio de tipo de vehículo; Cambio de tipo de servicio; Robo total del vehículo; Incendio, destrucción, desuso o desarme; y…', 'Los propietarios de los vehículos están obligados a reportar en forma inmediata a la autoridad estatal competente, los siguientes movimientos o eventos sobre los vehículos: Cambio de propietario; Cambio de domicilio; Cambio de tipo de vehículo; Cambio de tipo de servicio; Robo total del vehículo; Incendio, destrucción, desuso o desarme; y Recuperación después de un robo.', '28', '', '', 10, 15, false, null),
(12, 'Particular, público local o federal; Nombre, domicilio y teléfono de la persona física o moral para atención al público; y Tipo de carga', 'Los vehículos de carga con peso bruto mayor de 3,500-tres mil quinientos kilogramos, y todos aquellos que presten algún servicio (recolección, entrega, grúas) deberán llevar en sus puertas las leyendas siguientes: Tipo de servicio que puede ser: particular, público local o federal; Nombre, domicilio y teléfono de la persona física o moral para atención al público; y Tipo de carga.', '30', '', '', 3, 10, false, null),
(13, 'LLANTAS. - Los vehículos de 4-cuatro o más ruedas, deberán traer una llanta de refacción, así como herramienta en buen estado para su cambio', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LLANTAS. - Los vehículos de 4-cuatro o más ruedas, deberán traer una llanta de refacción, así como herramienta en buen estado para su cambio;', '31', 'I', '', 5, 15, false, null),
(14, 'F) Los frenos de servicio deberán permitir la reducción de velocidad y/o detención del vehículo de modo seguro, rápido y eficaz, cualquiera que sean las condiciones del camino;…', 'FRENOS. - Todo vehículo automotor, remolque o semirremolque deberá estar provisto de frenos que puedan ser accionados por el conductor desde su asiento; debiendo estar éstos en buen estado y actuar uniformemente en todas las llantas. Los pedales para accionar los frenos deberán estar cubiertos de hule o cualquier otro material antiderrapante que no se encuentre liso. Además, se deben satisfacer los requisitos siguientes: f) Los frenos de servicio deberán permitir la reducción de velocidad y/o detención del vehículo de modo seguro, rápido y eficaz, cualquiera que sean las condiciones del camino; g) Los remolques cuyo peso bruto total excedan del 50%-cincuenta por ciento del peso del vehículo que lo estira, deberán tener frenos de servicio y/o estacionamiento; h) Las motocicletas y bicicletas deberán contar con frenos de servicio independientes en cada una de las llantas; exceptuando las bicicletas que de fábrica únicamente cuentan con freno de pedal trasero; i) Los vehículos que utilicen aire comprimido para el funcionamiento de sus frenos, deberán estar provistos de un manómetro visible por el conductor que indique en kilogramos por centímetro cuadrado la presión disponible para el frenado. Así mismo, deberá indicar con una señal de advertencia fácilmente visible y/o audible estar por abajo del 50%-cincuenta por ciento de la presión dada por el manómetro; y j) Los frenos de estacionamiento deberán mantener inmóvil el vehículo al dejarlo estacionado sin importar las condiciones de la carga y del camino.', '31', 'II', '', 15, 20, false, null),
(15, 'Luces delanteras como mínimo con dos faros de circulación delanteros que emitan luz blanca, dotados de un mecanismo para cambio de intensidad; debiendo la luz baja iluminar un…', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces delanteras como mínimo con dos faros de circulación delanteros que emitan luz blanca, dotados de un mecanismo para cambio de intensidad; debiendo la luz baja iluminar un área no menor a 30-treinta metros y la luz alta un área no menor a 100-cien metros. En el tablero de control debe existir una señal luminosa que indique al conductor el uso de la luz alta;', '31', 'III', 'a', 5, 10, false, null),
(16, 'Circular con una luz indicadora de frenado', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces indicadoras de frenado en la parte trasera que emitan luz roja y sean visibles desde una distancia considerable. Estas luces deberán encenderse y aumentar de intensidad en forma automática al aplicarse los frenos; (circular con una luz indicadora de frenado).', '31', 'III', 'b', 3, 5, false, null),
(17, 'Circular sin luces indicadoras de frenado', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces indicadoras de frenado en la parte trasera que emitan luz roja y sean visibles desde una distancia considerable. Estas luces deberán encenderse y aumentar de intensidad en forma automática al aplicarse los frenos; (circular sin luces indicadoras de frenado).', '31', 'III', 'b', 15, 20, false, null),
(18, 'Luces direccionales de destello intermitente. Las delanteras deberán ser de color ámbar y las traseras de color rojo o ámbar', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces direccionales de destello intermitente. Las delanteras deberán ser de color ámbar y las traseras de color rojo o ámbar;', '31', 'III', 'c', 10, 15, false, null),
(19, 'Según fabricante', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luz blanca que ilumine la placa posterior (según fabricante);', '31', 'III', 'f', 3, 5, false, null),
(20, 'Según fabricante', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes. LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces indicadoras de reversa. Debiendo estar colocadas en la parte posterior y que emitan luz blanca al aplicar la reversa (según fabricante);', '31', 'III', 'g', 10, 15, false, null),
(21, 'Luces y/o reflejantes especiales según el tipo y dimensiones del vehículo. Para lo anterior, se aplicará lo establecido en el Reglamento de Tránsito para Carreteras Federales', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. 1.Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces y/o reflejantes especiales según el tipo y dimensiones del vehículo. Para lo anterior, se aplicará lo establecido en el Reglamento de Tránsito para Carreteras Federales;', '31', 'III', 'h', 10, 15, false, null),
(22, 'CINTURÓN DE SEGURIDAD. - Todos los vehículos automotores deberán contar con cinturón de seguridad adecuado según el fabricante y el modelo', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: CINTURÓN DE SEGURIDAD. - Todos los vehículos automotores deberán contar con cinturón de seguridad adecuado según el fabricante y el modelo;', '31', 'V', '', 12, 15, false, null),
(23, 'TAPÓN O TAPA DEL TANQUE DEL COMBUSTIBLE. - Este deberá ser de diseño original o universal. Debe evitarse el uso de madera, estopa, tela, botes o cualquier dispositivo', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: TAPÓN O TAPA DEL TANQUE DEL COMBUSTIBLE. - Este deberá ser de diseño original o universal. Debe evitarse el uso de madera, estopa, tela, botes o cualquier dispositivo;', '31', 'VI', '', 3, 5, false, null),
(24, 'Circular con parabrisas sin cristal, astillado o con fracturas', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: CRISTALES. -Todos los cristales de los vehículos automotores deberán estar en buenas condiciones, mantenerse limpios y libres de objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa. Todos los vehículos automotores deberán estar provistos de un cristal parabrisas transparente, inastillable y sin fracturas. (circular con parabrisas sin cristal, astillado o con fracturas).', '31', 'VIII', '', 10, 20, false, null),
(25, 'Circular con los cristales con objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa, polarizados u opacos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: CRISTALES. -Todos los cristales de los vehículos automotores deberán estar en buenas condiciones, mantenerse limpios y libres de objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa. Todos los vehículos automotores deberán estar provistos de un cristal parabrisas transparente, inastillable y sin fracturas. (circular con los cristales con objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa, polarizados u opacos).', '31', 'VIII', '', 70, 80, false, null),
(26, 'Circular con mofle o sistema de escape ruidoso o defectuoso', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: SISTEMA DE ESCAPE. - Todos los vehículos automotores deberán estar provistos de un sistema de escape para controlar la emisión de ruidos, gases y humos derivados del funcionamiento del motor. Este sistema deberá ajustarse a los siguientes requisitos: No deberá haber roturas o fugas en ninguno de sus componentes desde el motor hasta la salida; Ninguna parte de sus componentes deberá pasar a través del compartimento para los pasajeros; La salida del tubo de escape deberá estar colocada de manera que las emisiones de gases y humos salgan en un lugar más atrás del compartimento de pasajeros; sin que esta salida sobresalga más allá de la defensa posterior; Los vehículos de carga que utilizan combustible diésel, además de cumplir con lo establecido en los incisos anteriores, deberán tener la salida del tubo de escape por lo menos 15-quince centímetros más arriba de la parte superior de la carrocería; y Las motocicletas deberán contar con una protección en el sistema de escape, que impida el contacto directo del conductor o pasajero, para evitarles quemaduras. Es obligación de los conductores de vehículos evitar que estos emitan humos y gases contaminantes; el producir ostensiblemente contaminación al medio ambiente, será causa de Infracción Administrativa. El propietario contará con un término de 30-treinta días naturales para realizar lo conducente en su vehículo a fin de corregir la falla por la cual emita contaminantes, pudiendo circular durante dicho período sólo para conducirlo al taller mecánico para los efectos ya especificados. En caso de incumplimiento a lo dispuesto en este artículo, la multa será incrementada al doble de la impuesta y será retirado de la circulación. (circular con mofle o sistema de escape ruidoso o defectuoso).', '31', 'XI', '', 10, 15, false, null),
(27, 'Expedir humo o ruido en excesivo', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: SISTEMA DE ESCAPE. - Todos los vehículos automotores deberán estar provistos de un sistema de escape para controlar la emisión de ruidos, gases y humos derivados del funcionamiento del motor. Este sistema deberá ajustarse a los siguientes requisitos: No deberá haber roturas o fugas en ninguno de sus componentes desde el motor hasta la salida; Ninguna parte de sus componentes deberá pasar a través del compartimento para los pasajeros; La salida del tubo de escape deberá estar colocada de manera que las emisiones de gases y humos salgan en un lugar más atrás del compartimento de pasajeros; sin que esta salida sobresalga más allá de la defensa posterior; Los vehículos de carga que utilizan combustible diésel, además de cumplir con lo establecido en los incisos anteriores, deberán tener la salida del tubo de escape por lo menos 15-quince centímetros más arriba de la parte superior de la carrocería; y Las motocicletas deberán contar con una protección en el sistema de escape, que impida el contacto directo del conductor o pasajero, para evitarles quemaduras. Es obligación de los conductores de vehículos evitar que estos emitan humos y gases contaminantes; el producir ostensiblemente contaminación al medio ambiente, será causa de Infracción Administrativa. El propietario contará con un término de 30-treinta días naturales para realizar lo conducente en su vehículo a fin de corregir la falla por la cual emita contaminantes, pudiendo circular durante dicho período sólo para conducirlo al taller mecánico para los efectos ya especificados. En caso de incumplimiento a lo dispuesto en este artículo, la multa será incrementada al doble de la impuesta y será retirado de la circulación. (expedir humo o ruido en excesivo).', '31', 'XI', '', 15, 20, false, null),
(28, 'Zoqueteras', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: PANTALONERAS O CUBRELLANTAS. - Los vehículos de plataforma, caja, remolque, quinta rueda o de cualquier otro tipo en el que las llantas posteriores no tengan concha en la parte superior; deberán contar con pantaloneras (zoqueteras);', '31', 'XIII', '', 10, 15, false, null),
(29, 'ESPEJOS RETROVISORES. - Todo vehículo automotor deberá contar con un espejo retrovisor en su interior y espejos retrovisores laterales en el exterior del vehículo. Estos…', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: ESPEJOS RETROVISORES. - Todo vehículo automotor deberá contar con un espejo retrovisor en su interior y espejos retrovisores laterales en el exterior del vehículo. Estos deberán estar siempre limpios y sin roturas.', '31', 'XIV', '', 3, 5, false, null),
(30, 'DISPOSITIVOS PARA REMOLQUES. - Todos los remolques deberán tener además del dispositivo de unión al vehículo automotor, 2-dos cadenas adecuadas al peso de cada remolque;…', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: DISPOSITIVOS PARA REMOLQUES. - Todos los remolques deberán tener además del dispositivo de unión al vehículo automotor, 2-dos cadenas adecuadas al peso de cada remolque; debiendo ir una a cada lado del frente del remolque. Estas cadenas deberán unirse al vehículo automotor para evitar el desprendimiento total del remolque en caso de falla del dispositivo de unión;', '31', 'XVI', '', 10, 20, false, null),
(31, 'Ventanillas protegidas con malla metálica para evitar que los escolares saquen alguna parte de su cuerpo', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS DE TRANSPORTE ESCOLAR. - Los vehículos de transporte escolar deberán cumplir además con los siguientes requisitos: Ventanillas protegidas con malla metálica para evitar que los escolares saquen alguna parte de su cuerpo;', '31', 'XVII', 'a', 20, 25, false, null),
(32, 'Colores distintivos, ámbar con una franja blanca y leyendas en color negro', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS DE TRANSPORTE ESCOLAR. - Los vehículos de transporte escolar deberán cumplir además con los siguientes requisitos: Colores distintivos, ámbar con una franja blanca y leyendas en color negro;', '31', 'XVII', 'b', 15, 20, false, null),
(33, 'PELIGRO, MATERIAL EXPLOSIVO, FLAMABLE, TÓXICO O PELIGROSO. Lo anterior, además de cumplir con lo que establece la Sección 5 del Capítulo III', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS TRANSPORTADORES DE CARGA PELIGROSA. - Los vehículos transportadores de materiales explosivos, flamables, tóxicos o peligrosos de cualquier índole, deberán llevar en la parte posterior y en los lados las leyendas siguientes: PELIGRO, MATERIAL EXPLOSIVO, FLAMABLE, TÓXICO O PELIGROSO. Lo anterior, además de cumplir con lo que establece la Sección 5 del Capítulo III;', '31', 'XVIII', '', 25, 35, false, null),
(34, 'VEHÍCULOS CONDUCIDOS POR PERSONAS CON DISCAPACIDAD. - Los vehículos que sean conducidos por personas con discapacidad deberán contar con los dispositivos especiales para cada…', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS CONDUCIDOS POR PERSONAS CON DISCAPACIDAD. - Los vehículos que sean conducidos por personas con discapacidad deberán contar con los dispositivos especiales para cada caso. Estos y los que transportan a personas con discapacidad deberán contar con placas expedidas por la autoridad competente en donde aparezca el emblema correspondiente, para que puedan hacer uso de los lugares exclusivos. Estos vehículos no podrán hacer uso de los lugares exclusivos cuando no sean conducidos por personas con discapacidad o bien cuando no transporten a éstos.', '31', 'XIX', '', 3, 5, false, null),
(35, 'Faros encendidos o reflejantes de colores diferentes al blanco o ámbar en la parte delantera', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Faros encendidos o reflejantes de colores diferentes al blanco o ámbar en la parte delantera;', '32', 'I', '', 10, 20, false, null),
(36, 'Faros encendidos o reflejantes de colores diferentes al rojo o ámbar en la parte posterior; con excepción solamente de las luces de reversa y de placa', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Faros encendidos o reflejantes de colores diferentes al rojo o ámbar en la parte posterior; con excepción solamente de las luces de reversa y de placa;', '32', 'II', '', 10, 20, false, null),
(37, 'Radios que utilicen la frecuencia de la Dependencia de Policía Vial correspondiente o cualquier otro cuerpo de seguridad', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Radios que utilicen la frecuencia de la Dependencia de Policía Vial correspondiente o cualquier otro cuerpo de seguridad;', '32', 'IV', '', 20, 30, false, null),
(38, 'Circular con sirena abierta los vehículos no autorizados', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Sirena o aparatos que emitan sonidos semejantes a ella, torreta y/o luces estroboscópicas de cualquier color con excepción de los vehículos oficiales, de emergencia o especiales; (circular con sirena abierta los vehículos no autorizados).', '32', 'VI', '', 20, 25, false, null),
(39, 'Utilizar luces estroboscópicas en vehículos no autorizados', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Sirena o aparatos que emitan sonidos semejantes a ella, torreta y/o luces estroboscópicas de cualquier color con excepción de los vehículos oficiales, de emergencia o especiales; (utilizar luces estroboscópicas en vehículos no autorizados).', '32', 'VI', '', 20, 30, false, null),
(40, 'Los vehículos de transporte de carga pesada deberán circular por las vías que forman parte de la red troncal, establecida en el presente Reglamento, de forma obligatoria por…', 'Los vehículos de transporte de carga pesada deberán circular por las vías que forman parte de la red troncal, establecida en el presente Reglamento, de forma obligatoria por los carriles establecidos para su circulación, siendo éstos los carriles derechos; a excepción de los ya señalizados.', '44', '', '', 30, 50, false, null),
(41, 'Los vehículos de transporte de materiales, sustancias o residuos peligrosos a granel, que no tengan destino final el área metropolitana de Monterrey obligatoriamente deberán…', 'Los vehículos de transporte de materiales, sustancias o residuos peligrosos a granel, que no tengan destino final el área metropolitana de Monterrey obligatoriamente deberán hacer uso de los libramientos periféricos. Para los casos en que se tenga como origen el área metropolitana de Monterrey, deberá sujetarse a las rutas que al efecto se establezcan, y sean acordadas por los Municipios, la Secretaría de Comunicaciones y Transportes, Protección Civil y la Industria.', '46', '', '', 30, 50, false, null),
(42, 'Son vías restringidas para la circulación de vehículos de transporte de carga pesada, aquellas que conforman el primer cuadro del Municipio, las calles y avenidas de…', 'Son vías restringidas para la circulación de vehículos de transporte de carga pesada, aquellas que conforman el primer cuadro del Municipio, las calles y avenidas de fraccionamientos habitacionales.', '47', '', '', 30, 50, false, null),
(43, 'Los vehículos de transporte de carga pesada con tractor doblemente articulado, es decir con una configuración T-S-R (tracto camión-semirremolque- remolque), T-S-S (tracto…', 'Los vehículos de transporte de carga pesada con tractor doblemente articulado, es decir con una configuración T-S-R (tracto camión-semirremolque- remolque), T-S-S (tracto camión-semiremolque- semiremolque) o C-R (camión-remolque), podrán circular por las vías que forman parte de la red troncal, a excepción de aquellas vueltas o retornos en los tramos de vías que por su diseño geométrico no permitan la circulación de estas unidades, mismas que estarán debidamente señalizadas.', '49', '', '', 50, 100, false, null),
(44, 'Circular los vehículos de transporte de carga o tracto camiones trasgrediendo restricciones o incumpliendo condiciones establecidas por la autoridad municipal', 'La autoridad municipal podrá otorgar permiso para la circulación de alguno(s) vehículo(s) de transporte de carga pesada por las vías restringidas del Municipio, en los siguientes supuestos: Para la carga o descarga y/o prestación de un bien o servicio que se lleve a cabo de forma extraordinaria e imprescindible dentro del Municipio; Cuando se cuente con un permiso de construcción emitido por la autoridad correspondiente; y Las demás que la autoridad municipal correspondiente considere como circunstancias especiales. La autoridad municipal analizará cada caso en específico señalando con claridad en el permiso la fecha de expedición, ruta, vigencia, horario y demás condiciones que se requieran. Para la obtención del permiso para circular por las vías restringidas, el interesado deberá presentar los siguientes documentos vigentes en los días y horarios establecidos por la autoridad municipal que corresponda: Solicitud por escrito o en su caso de forma electrónica, señalando ruta, horario, tipo de carga, tipo de vehículo, así como la empresa originaria y destinataria; Factura o contrato de arrendamiento que acredite la propiedad o posesión legal del vehículo en original o certificada; Tarjeta de circulación en original o certificada; Póliza de seguro de responsabilidad civil por daños a terceros en copia certificada; Licencia de conducir acorde con el vehículo; y Permiso o licencia de construcción en su caso. Se podrán realizar los trámites para la obtención de permisos para circular por vías restringidas a través de sistemas o medios tecnológicos que se designen para tal efecto. (circular los vehículos de transporte de carga o tracto camiones trasgrediendo restricciones o incumpliendo condiciones establecidas por la autoridad municipal).', '50', '', '', 15, 40, true, null),
(45, 'Circular por las vías restringidas sin permiso correspondiente, los transportes de carga', 'La autoridad municipal podrá otorgar permiso para la circulación de alguno(s) vehículo(s) de transporte de carga pesada por las vías restringidas del Municipio, en los siguientes supuestos: Para la carga o descarga y/o prestación de un bien o servicio que se lleve a cabo de forma extraordinaria e imprescindible dentro del Municipio; Cuando se cuente con un permiso de construcción emitido por la autoridad correspondiente; y Las demás que la autoridad municipal correspondiente considere como circunstancias especiales. La autoridad municipal analizará cada caso en específico señalando con claridad en el permiso la fecha de expedición, ruta, vigencia, horario y demás condiciones que se requieran. Para la obtención del permiso para circular por las vías restringidas, el interesado deberá presentar los siguientes documentos vigentes en los días y horarios establecidos por la autoridad municipal que corresponda: Solicitud por escrito o en su caso de forma electrónica, señalando ruta, horario, tipo de carga, tipo de vehículo, así como la empresa originaria y destinataria; Factura o contrato de arrendamiento que acredite la propiedad o posesión legal del vehículo en original o certificada; Tarjeta de circulación en original o certificada; Póliza de seguro de responsabilidad civil por daños a terceros en copia certificada; Licencia de conducir acorde con el vehículo; y Permiso o licencia de construcción en su caso. Se podrán realizar los trámites para la obtención de permisos para circular por vías restringidas a través de sistemas o medios tecnológicos que se designen para tal efecto. (circular por las vías restringidas sin permiso correspondiente, los transportes de carga).', '50', '', '', 30, 50, true, null),
(46, 'Transportar en vehículos abiertos, material que despida mal olor', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Transportar en vehículos abiertos, material que despida mal olor;', '54', 'II', '', 20, 30, false, null),
(47, 'Transportar en vehículos abiertos, cadáveres de animales', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Transportar en vehículos abiertos, cadáveres de animales;', '54', 'III', '', 15, 20, false, null),
(48, 'Transportar explosivos y material peligroso sin autorización o sin el equipamiento especial para tal efecto', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Transportar explosivos y material peligroso sin autorización o sin el equipamiento especial para tal efecto', '54', 'IV', '', 50, 200, true, null),
(49, 'Obstruir uno o más carriles de circulación por caída parcial o total de la carga', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Obstruir uno o más carriles de circulación por caída parcial o total de la carga.', '54', 'VI', '', 50, 200, false, null),
(50, 'Derramar concreto o algún material similar sobre uno o más carriles de circulación', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Derramar concreto o algún material similar sobre uno o más carriles de circulación.', '54', 'VII', '', 50, 200, false, null),
(51, 'Acomodar la carga dentro de los límites laterales del vehículo y de forma que no obstruya su visibilidad', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Acomodar la carga dentro de los límites laterales del vehículo y de forma que no obstruya su visibilidad;', '55', 'I', '', 15, 20, false, null),
(52, 'Transportar carga que se esparza sin mojarla, sujetarla o cubrirla', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Cubrir, mojar y sujetar al vehículo la carga que pueda esparcirse y sujetar debidamente los cables tensores, lonas y demás accesorios que sujeten la carga; (transportar carga que se esparza sin mojarla, sujetarla o cubrirla).', '55', 'II', '', 20, 30, false, null),
(53, 'Transportar carga con cables, lonas, y accesorios sin estar debidamente sujetos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Cubrir, mojar y sujetar al vehículo la carga que pueda esparcirse y sujetar debidamente los cables tensores, lonas y demás accesorios que sujeten la carga; (transportar carga con cables, lonas, y accesorios sin estar debidamente sujetos).', '55', 'II', '', 20, 30, false, null),
(54, 'Que el peso y dimensiones de la carga cumplan con la Norma Oficial Mexicana correspondiente', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Que el peso y dimensiones de la carga cumplan con la Norma Oficial Mexicana correspondiente;', '55', 'III', '', 50, 100, false, null),
(55, 'Transportar carga sobresaliente hacia atrás más de lo permitido', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Proteger durante el día con banderolas rojas de un tamaño no menor a 50-cincuenta centímetros por lado la carga que sobresalga a la parte posterior del vehículo. De noche esta protección será con luces rojas visibles por lo menos desde 300-trescientos metros. En ningún caso la carga sobresaliente podrá tener longitud mayor a la cuarta parte de la longitud del vehículo. No se podrá transportar carga sobresaliente cuando las condiciones climatológicas dificulten la conducción; (transportar carga sobresaliente hacia atrás más de lo permitido).', '55', 'IV', '', 10, 15, false, null),
(56, 'Transportar carga sobresaliente sin protección', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Proteger durante el día con banderolas rojas de un tamaño no menor a 50-cincuenta centímetros por lado la carga que sobresalga a la parte posterior del vehículo. De noche esta protección será con luces rojas visibles por lo menos desde 300-trescientos metros. En ningún caso la carga sobresaliente podrá tener longitud mayor a la cuarta parte de la longitud del vehículo. No se podrá transportar carga sobresaliente cuando las condiciones climatológicas dificulten la conducción; (transportar carga sobresaliente sin protección).', '55', 'IV', '', 10, 15, false, null),
(57, 'Portar la autorización correspondiente cuando transporte explosivos, material tóxico o materiales peligrosos. En este caso el vehículo deberá contar con las características…', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Portar la autorización correspondiente cuando transporte explosivos, material tóxico o materiales peligrosos. En este caso el vehículo deberá contar con las características adecuadas para transportar dicha carga; de acuerdo al Reglamento para el Transporte Terrestre de Materiales y Residuos Peligrosos;', '55', 'V', '', 30, 50, false, null),
(58, 'Transportar carga que arrastre o pueda caerse', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Abstenerse de utilizar personas para sujetar la carga y abstenerse de transportar carga que arrastre. (transportar carga que arrastre o pueda caerse).', '55', 'VI', '', 15, 20, false, null),
(59, 'Utilizar personas para proteger o sujetar carga', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Abstenerse de utilizar personas para sujetar la carga y abstenerse de transportar carga que arrastre. (utilizar personas para proteger o sujetar carga).', '55', 'VI', '', 15, 20, false, null),
(60, 'No respetar indicaciones de promotores voluntarios', 'Los conductores de vehículos deberán cumplir con lo siguiente: Acatar todas las disposiciones dictadas por el personal municipal designado para la vigilancia del tránsito y de los promotores voluntarios de seguridad vial autorizados por la Secretaría. En casos de emergencia o de siniestros, deberán acatar también cualquier disposición de los miembros de los cuerpos de seguridad, auxilio o rescate; (no respetar indicaciones de promotores voluntarios).', '56', 'I', '', 5, 10, false, null),
(61, 'No respetar indicaciones del Policía Vial', 'Los conductores de vehículos deberán cumplir con lo siguiente: Acatar todas las disposiciones dictadas por el personal municipal designado para la vigilancia del tránsito y de los promotores voluntarios de seguridad vial autorizados por la Secretaría. En casos de emergencia o de siniestros, deberán acatar también cualquier disposición de los miembros de los cuerpos de seguridad, auxilio o rescate; (no respetar indicaciones del Policía Vial).', '56', 'I', '', 25, 50, false, null),
(62, 'Circular con las puertas cerradas de sus vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Circular con las puertas cerradas de sus vehículos;', '56', 'II', '', 15, 20, false, null),
(63, 'Utilizar el cinturón de seguridad y hacer que los pasajeros hagan lo mismo. Para el caso de menores de 7-siete años, se ajustará a lo ordenado por el artículo 57 del presente…', 'Los conductores de vehículos deberán cumplir con lo siguiente: Utilizar el cinturón de seguridad y hacer que los pasajeros hagan lo mismo. Para el caso de menores de 7-siete años, se ajustará a lo ordenado por el artículo 57 del presente Reglamento;', '56', 'IV', '', 12, 15, false, null),
(64, 'Ascender y descender pasajeros a una distancia no mayor de 50-cincuenta centímetros de la banqueta o acotamiento', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ascender y descender pasajeros a una distancia no mayor de 50-cincuenta centímetros de la banqueta o acotamiento;', '56', 'V', '', 20, 30, false, null),
(65, 'Ceder el paso a personas con discapacidad en cualquier lugar y respetar los “Exclusivos” para éstos en áreas públicas y/o privadas con acceso al público', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ceder el paso a personas con discapacidad en cualquier lugar y respetar los “Exclusivos” para éstos en áreas públicas y/o privadas con acceso al público;', '56', 'VI', '', 20, 30, false, null),
(66, 'Ceder el paso a los peatones que en zonas de cruce permitidas que se encuentren sobre los carriles de circulación o hayan iniciado el cruce de éstos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ceder el paso a los peatones que en zonas de cruce permitidas que se encuentren sobre los carriles de circulación o hayan iniciado el cruce de éstos;', '56', 'VII', '', 10, 15, false, null),
(67, 'Ceder el paso a los peatones cuando se tenga que atravesar la banqueta, al entrar o salir de cocheras o estacionamientos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ceder el paso a los peatones cuando se tenga que atravesar la banqueta, al entrar o salir de cocheras o estacionamientos;', '56', 'VIII', '', 10, 15, false, null),
(68, 'No respetar paso de vehículos sobre rieles', 'Los conductores de vehículos deberán cumplir con lo siguiente: Hacer alto en cruce de vía férrea; (no respetar paso de vehículos sobre rieles).', '56', 'IX', '', 20, 30, false, null),
(69, 'No hacer alto en la vía de ferrocarril', 'Los conductores de vehículos deberán cumplir con lo siguiente: Hacer alto en cruce de vía férrea; (no hacer alto en la vía de ferrocarril).', '56', 'IX', '', 20, 30, false, null),
(70, 'Utilizar solamente un carril a la vez', 'Los conductores de vehículos deberán cumplir con lo siguiente: Utilizar solamente un carril a la vez;', '56', 'X', '', 15, 20, false, null),
(71, 'Usar anteojos o cualquier dispositivo cuando así lo tenga indicado por prescripción médica como necesarios para conducir vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Usar anteojos o cualquier dispositivo cuando así lo tenga indicado por prescripción médica como necesarios para conducir vehículos;', '56', 'XII', '', 5, 10, false, null),
(72, 'Entregar al personal designado de la autoridad municipal su licencia de conducir si cuenta con ella físicamente o vía electrónica si es digital y la tiene en su dispositivo…', 'Los conductores de vehículos deberán cumplir con lo siguiente: Entregar al personal designado de la autoridad municipal su licencia de conducir si cuenta con ella físicamente o vía electrónica si es digital y la tiene en su dispositivo móvil, la tarjeta de circulación del vehículo y póliza de seguro vigente cuando se le soliciten. En caso de hechos de tránsito y/o Infracción Administrativa, los documentos serán retenidos por el Policía Vial sólo si las placas del vehículo no son expedidas por la autoridad competente en el Estado de Nuevo León;', '56', 'XIII', '', 10, 15, false, null),
(73, 'Iniciar la marcha con precaución y gradualmente, cediendo el paso a los vehículos que estando en movimiento, estén rebasando al vehículo detenido para adelantarlo y también a…', 'Los conductores de vehículos deberán cumplir con lo siguiente: Iniciar la marcha con precaución y gradualmente, cediendo el paso a los vehículos que estando en movimiento, estén rebasando al vehículo detenido para adelantarlo y también a los vehículos en movimiento en forma transversal al vehículo detenido; si esto ocurre en un crucero o intersección;', '56', 'XV', '', 15, 20, false, null),
(74, 'Negarse al examen de alcohol o drogas', 'Los conductores de vehículos deberán cumplir con lo siguiente: Someterse a un examen para determinar los grados de alcohol en la sangre o su equivalente en cualquier otro sistema de medición, o bien, para detectar la influencia de drogas o estupefacientes, cuando le sea requerido por el personal autorizado del Municipio;', '56', 'XVI', '', 50, 200, true, null),
(75, 'Reducir la velocidad ante cualquier concentración de peatones y/o vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Reducir la velocidad ante cualquier concentración de peatones y/o vehículos.', '56', 'XVIII', '', 15, 20, false, null),
(76, 'No utilizar sistema de retención infantil (menores de 7 años)', 'Los conductores de automóviles que viajen con pasajeros menores de 7-siete años de edad, deberán asegurarse que éstos ocupen una de las plazas traseras sobre la hilera inmediatamente posterior a los asientos del conductor o del copiloto que cuente con cinturón de seguridad de tres puntos. Los menores de 7-siete años deberán ser transportados en un Sistema de Retención Infantil o asiento elevador debidamente colocado, que cumpla con certificación estandarizada, con un sistema de anclaje adecuado y que se ajuste a las características indicadas en el Anexo 2 de este Reglamento. Únicamente si el vehículo no cuenta con asiento trasero, los menores de 7-siete años podrán viajar en el asiento delantero, siempre y cuando cuenten con espacio suficiente para instalar un Sistema de Retención Infantil acordes a su peso o talla y se desactive el sistema de bolsas de aire.', '57', 'Anexo 2', '', 15, 20, true, null),
(77, 'Conducir bajo los efectos de medicamentos que alteren las facultades', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. Para la aplicación de esta fracción se tomará en consideración lo establecido en el Reglamento de Justicia Cívica del Municipio de San Pedro Garza García, Nuevo León, así como determinará los medios que se utilizarán para la detección de estos casos; (Conducir bajo los efectos de medicamentos que alteren las facultades).', '58', 'I', '', 30, 200, false, null),
(78, 'Conducir bajo el influjo de drogas o sustancias tóxicas', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. Para la aplicación de esta fracción se tomará en consideración lo establecido en el Reglamento de Justicia Cívica del Municipio de San Pedro Garza García, Nuevo León, así como determinará los medios que se utilizarán para la detección de estos casos; (Conducir bajo el influjo de drogas o sustancias tóxicas).', '58', 'I', '', 50, 200, true, null),
(79, 'Conducir en estado de ebriedad', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. Para la aplicación de esta fracción se tomará en consideración lo establecido en el Reglamento de Justicia Cívica del Municipio de San Pedro Garza García, Nuevo León, así como determinará los medios que se utilizarán para la detección de estos casos; (Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad)', '58', 'I', '', 50, 200, true, 'Conducir en estado de ebriedad'),
(80, 'Conducir en estado de ebriedad y cometer otra infracción', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. Para la aplicación de esta fracción se tomará en consideración lo establecido en el Reglamento de Justicia Cívica del Municipio de San Pedro Garza García, Nuevo León, así como determinará los medios que se utilizarán para la detección de estos casos; (Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad y cometer cualquier Infracción Administrativa al presente Reglamento).', '58', 'I', '', 100, 300, true, null),
(81, 'Conducir en estado de ebriedad (reincidente)', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. Para la aplicación de esta fracción se tomará en consideración lo establecido en el Reglamento de Justicia Cívica del Municipio de San Pedro Garza García, Nuevo León, así como determinará los medios que se utilizarán para la detección de estos casos; (Conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad en forma reincidente).', '58', 'I', '', 200, 600, true, null),
(82, 'Sujetar el celular u otro aparato electrónico al conducir', 'Los conductores de vehículos tienen prohibido lo siguiente: Sujetar, con una o ambas manos, aparatos de telecomunicación, teléfonos celulares, radios o cualquier aparato electrónico u objeto de las nuevas tecnologías de la información y comunicación, que puedan distraer al conductor al momento de conducir un vehículo. Se exceptúa de lo anterior, a los conductores de las unidades de seguridad, de conformidad con lo establecido en la Ley de Seguridad Pública para el Estado de Nuevo León; así como a las unidades de asistencia médica, protección civil, bomberos y de emergencias, dada la naturaleza de sus funciones;', '58', 'II', '', 20, 30, true, 'Uso de celular al conducir'),
(83, 'Entorpecer la circulación de vehículos excepto en el caso en que el vehículo no funcione o bien se haya participado en un hecho de tránsito', 'Los conductores de vehículos tienen prohibido lo siguiente: Entorpecer la circulación de vehículos excepto en el caso en que el vehículo no funcione o bien se haya participado en un hecho de tránsito;', '58', 'III', '', 15, 20, false, null),
(84, 'Transportar personas en el exterior del vehículo o en lugar no especificado para el transporte de pasajeros', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar personas en el exterior del vehículo o en lugar no especificado para el transporte de pasajeros;', '58', 'IV', '', 5, 15, false, null),
(85, 'Entorpecer la marcha de desfiles o manifestaciones permitidas, cortejos fúnebres o eventos deportivos autorizados en la vía pública', 'Los conductores de vehículos tienen prohibido lo siguiente: Entorpecer la marcha de desfiles o manifestaciones permitidas, cortejos fúnebres o eventos deportivos autorizados en la vía pública;', '58', 'V', '', 10, 15, false, null),
(86, 'Efectuar competencias de cualquier tipo con sus vehículos sin autorización de la autoridad municipal', 'Los conductores de vehículos tienen prohibido lo siguiente: Efectuar competencias de cualquier tipo con sus vehículos sin autorización de la autoridad municipal;', '58', 'VI', '', 20, 50, false, null),
(87, 'Llevar consigo aparatos que hagan uso de la frecuencia de radio de la autoridad municipal u otro cuerpo de seguridad', 'Los conductores de vehículos tienen prohibido lo siguiente: Llevar consigo aparatos que hagan uso de la frecuencia de radio de la autoridad municipal u otro cuerpo de seguridad;', '58', 'VII', '', 20, 30, false, null),
(88, 'Utilizar equipos de sonido de tal forma que su volumen sea molesto para el ciudadano o pasajeros en caso de transporte de servicio público', 'Los conductores de vehículos tienen prohibido lo siguiente: Utilizar equipos de sonido de tal forma que su volumen sea molesto para el ciudadano o pasajeros en caso de transporte de servicio público;', '58', 'VIII', '', 10, 15, false, null),
(89, 'Utilizar audífonos con excepción de aquellos aparatos que cuenten con un solo auricular', 'Los conductores de vehículos tienen prohibido lo siguiente: Utilizar audífonos con excepción de aquellos aparatos que cuenten con un solo auricular;', '58', 'IX', '', 10, 15, false, null),
(90, 'Ascenso o descenso de pasaje sobre el segundo carril de circulación', 'Los conductores de vehículos tienen prohibido lo siguiente: Ascenso o descenso de pasaje sobre el segundo carril de circulación;', '58', 'X', '', 20, 30, false, null),
(91, 'Circular a los lados, adelante o atrás de vehículos de emergencia que estén haciendo uso de su sirena o de torretas de luz roja, azul, blanca o ámbar', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular a los lados, adelante o atrás de vehículos de emergencia que estén haciendo uso de su sirena o de torretas de luz roja, azul, blanca o ámbar;', '58', 'XI', '', 20, 30, false, null),
(92, 'Circular sobre las mangueras de bomberos o de protección civil, banquetas o zonas exclusivas para uso de peatones, parques públicos, camellones, barreras que dividan carriles…', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular sobre las mangueras de bomberos o de protección civil, banquetas o zonas exclusivas para uso de peatones, parques públicos, camellones, barreras que dividan carriles de circulación opuesta o canalicen carriles de movimiento específico de circulación, barreras o dispositivos para la protección de obras u obstáculos en la vía pública y sus marcas de aproximación;', '58', 'XII', '', 8, 20, false, null),
(93, 'Circular en sentido contrario', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular en sentido contrario, a menos que así lo indique la autoridad facultada, o bien, los señalamientos o dispositivos viales;', '58', 'XIII', '', 15, 20, false, 'Circular en sentido contrario'),
(94, 'Circular con vehículos o encender sus motores cuando éstos expidan humo o ruidos excesivos', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular con vehículos o encender sus motores cuando éstos expidan humo o ruidos excesivos;', '58', 'XIV', '', 15, 20, false, null),
(95, 'Permitir a terceros el uso de dispositivos de control y manejo del vehículo en movimiento', 'Los conductores de vehículos tienen prohibido lo siguiente: Permitir a terceros el uso de dispositivos de control y manejo del vehículo en movimiento;', '58', 'XV', '', 10, 15, false, null),
(96, 'Circular por los carriles exclusivos para el transporte confinado, por espacios o infraestructura ciclista y peatonal, exceptuando cualquier tipo de vehículo de emergencia', 'Circular por los carriles exclusivos para el transporte confinado, por espacios o infraestructura ciclista y peatonal, exceptuando cualquier tipo de vehículo de emergencia;', '58', 'XVI', '', 10, 15, false, null),
(97, 'Circular por los carriles exclusivos para vehículo compartido, exceptuado cualquier tipo de vehículo de emergencia', 'Circular por los carriles exclusivos para vehículo compartido, exceptuado cualquier tipo de vehículo de emergencia;', '58', 'XVII', '', 10, 15, false, null),
(98, 'Empalmarse con otro vehículo o rebasarlo utilizando un mismo carril de circulación, o hacer uso de más de un carril a la vez', 'Los conductores de vehículos tienen prohibido lo siguiente: Empalmarse con otro vehículo o rebasarlo utilizando un mismo carril de circulación, o hacer uso de más de un carril a la vez;', '58', 'XVIII', '', 10, 15, false, null),
(99, 'Transportar pasajeros en estado de ebriedad o bajo el influjo de alguna droga o enervante, en autobuses y camiones de pasajeros de servicio público de transporte', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar pasajeros en estado de ebriedad o bajo el influjo de alguna droga o enervante, en autobuses y camiones de pasajeros de servicio público de transporte;', '58', 'XIX', '', 5, 10, false, null),
(100, 'Transportar animales sin los dispositivos adecuados de sujeción, entendiéndose por estos correas o pecheras con adaptador especial para el cinturón de seguridad, cajas…', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar animales sin los dispositivos adecuados de sujeción, entendiéndose por estos correas o pecheras con adaptador especial para el cinturón de seguridad, cajas transportadoras, barreras que imposibiliten el acceso del animal al asiento del conductor, entre otros, de acuerdo a lo previsto en el Anexo 3 del presente Reglamento de los Dispositivos de Protección Animal. Cuando el animal viaje en las cajas de las camionetas tipo pick up, los animales invariablemente deberán ir dentro de cajas transportadoras de tamaño adecuado para cada animal, mismas que a su vez deben ir sujetas de manera firme al interior de la caja;', '58', 'XX', '', 10, 15, false, null),
(101, 'Conducir con personas, animales u objetos que obstruyan o limiten las maniobras de manejo', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir con personas, animales u objetos que obstruyan o limiten las maniobras de manejo;', '58', 'XXI', '', 5, 10, false, null),
(102, 'Remolcar vehículos si no se cuenta con el equipo especial para ello', 'Los conductores de vehículos tienen prohibido lo siguiente: Remolcar vehículos si no se cuenta con el equipo especial para ello;', '58', 'XXII', '', 10, 15, false, null),
(103, 'Transportar más de dos pasajeros en el asiento delantero de cualquier tipo de vehículo, en caso de ser asiento individual. Se permite sólo un pasajero en cada asiento; se…', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar más de dos pasajeros en el asiento delantero de cualquier tipo de vehículo, en caso de ser asiento individual. Se permite sólo un pasajero en cada asiento; se prohíbe que un pasajero viaje encima de otro. La cantidad de pasajeros lo determinará el fabricante, excluyéndose los vehículos modificados; Poseer, en el área de pasajeros de un vehículo, una botella, lata u otro envase que contenga una bebida alcohólica que haya sido abierta o que tenga los sellos rotos o el contenido parcialmente consumido; no se considerará como área de pasajeros aquella con asientos habilitados para carga;', '58', 'XXIII', '', 10, 15, false, null),
(104, 'Efectuar compraventa de productos y servicios en cruceros y vía pública en general cuando entorpezca la vialidad', 'Efectuar compraventa de productos y servicios en cruceros y vía pública en general cuando entorpezca la vialidad;', '58', 'XXIV', '', 10, 15, false, null),
(105, 'Obstaculizar la intersección', 'Avanzar a través de un crucero o intersección cuando no haya espacio suficiente para el vehículo (obstaculizar la intersección);', '58', 'XXV', '', 10, 15, false, null),
(106, 'Manifestar una conducta evidente de hostigamiento hacia otros conductores haciendo mal uso del vehículo que conduce', 'Los conductores de vehículos tienen prohibido lo siguiente: Manifestar una conducta evidente de hostigamiento hacia otros conductores haciendo mal uso del vehículo que conduce;', '58', 'XXVI', '', 15, 20, false, null),
(107, 'Conducir el vehículo con un aparato de televisión encendido, ubicado en el tablero, asiento delantero o adherido al vehículo, de manera que el conductor del mismo pueda…', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir el vehículo con un aparato de televisión encendido, ubicado en el tablero, asiento delantero o adherido al vehículo, de manera que el conductor del mismo pueda observar la pantalla del aparato televisivo; así como sostener el conductor, pasajero o acompañante el aparato de televisión encendido, de manera que el conductor pueda observar la pantalla del mismo;', '58', 'XXVII', '', 15, 20, false, null),
(108, 'Poseer, en el área de pasajeros de un vehículo, una botella, lata u otro envase que contenga una bebida alcohólica que haya sido abierta o que tenga los sellos rotos o el…', 'Los conductores de vehículos tienen prohibido lo siguiente: Poseer, en el área de pasajeros de un vehículo, una botella, lata u otro envase que contenga una bebida alcohólica que haya sido abierta o que tenga los sellos rotos o el contenido parcialmente consumido; no se considerará como área de pasajeros aquella con asientos habilitados para carga;', '58', 'XXVIII', '', 50, 200, true, null),
(109, 'Permitir la suplantación como conductor por otra persona, en un hecho de tránsito', 'Los conductores de vehículos tienen prohibido lo siguiente: Permitir la suplantación como conductor por otra persona, en un hecho de tránsito;', '58', 'XXIX', '', 50, 200, false, null),
(110, 'Permitir el ascenso y descenso de pasajeros en lugares no autorizados para los vehículos del servicio público local o federal de pasajeros', 'Los conductores de vehículos tienen prohibido lo siguiente: Permitir el ascenso y descenso de pasajeros en lugares no autorizados para los vehículos del servicio público local o federal de pasajeros;', '58', 'XXX', '', 15, 20, false, null),
(111, 'Arrojar basura u objetos a la vía pública', 'Arrojar basura u objetos a la vía pública.', '58', 'XXXI', '', 15, 20, false, null),
(112, 'Exceder la velocidad máxima de 50 km/h', 'La velocidad máxima en el Municipio es de 50- cincuenta kilómetros por hora, excepto en los lugares en los que se especifique mediante el señalamiento respectivo una velocidad diferente.', '59', 'primer párrafo', '', 12, 15, true, 'Exceso de velocidad'),
(113, 'Exceder 30 km/h en zona y horario escolar', 'La velocidad máxima es de 30-treinta kilómetros por hora en zonas y horarios escolares, dichos horarios serán de 7:00 a 9:30, de 11:30 a 14:30 y 16:30 a 18:30 horas, en días hábiles escolares; así mismo en caso de que por necesidad de horario de algún plantel escolar sea distinto, deberá de hacer la solicitud al área pertinente del Municipio para su implementación y señalización;', '59', 'I', '', 20, 30, true, null),
(114, 'Exceder 30 km/h frente a hospitales, parques, zonas habitacionales o concentraciones de peatones', 'La velocidad máxima es de 30-treinta kilómetros por hora frente a hospitales, parques infantiles y lugares de recreo, zonas habitacionales y ante concentraciones de peatones;', '59', 'II', '', 12, 15, false, null),
(115, 'La velocidad máxima es de 30-treinta kilómetros por hora en cualquier circunstancia en que la visibilidad y las condiciones del camino (tramos en reparación, pavimento dañado,…', 'La velocidad máxima es de 30-treinta kilómetros por hora en cualquier circunstancia en que la visibilidad y las condiciones del camino (tramos en reparación, pavimento dañado, grava suelta, etc.), y/o el factor climatológico (nieve, lluvia, niebla, etc.), estén por debajo de los límites normales;', '59', 'III', '', 12, 15, false, null),
(116, 'La velocidad máxima es de 10-diez kilómetros por hora en estacionamientos y establecimientos que permitan el acceso a vehículos; y', 'La velocidad máxima es de 10-diez kilómetros por hora en estacionamientos y establecimientos que permitan el acceso a vehículos; y', '59', 'IV', '', 12, 15, false, null),
(117, 'Los vehículos de peso bruto mayor a 3,500-tres mil quinientos kilogramos, los de servicio público colectivo de pasajeros, los de transporte escolar y los que transporten…', 'Los vehículos de peso bruto mayor a 3,500-tres mil quinientos kilogramos, los de servicio público colectivo de pasajeros, los de transporte escolar y los que transporten material explosivo o peligroso, deberán limitar su velocidad a 50-cincuenta kilómetros por hora, aun cuando haya señales que autoricen velocidad mayor, debiendo circular por los carriles derechos.', '59', 'V', '', 12, 15, false, null),
(118, 'Usar casco protector el conductor y en su caso su acompañante, así como portar lentes u otros protectores oculares', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: Usar casco protector el conductor y en su caso su acompañante, así como portar lentes u otros protectores oculares;', '61', 'I', '', 15, 20, false, null),
(119, 'No efectuar piruetas o zigzaguear', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No efectuar piruetas o zigzaguear;', '61', 'II', '', 20, 40, false, null),
(120, 'No remolcar o empujar otro vehículo', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No remolcar o empujar otro vehículo;', '61', 'III', '', 10, 15, false, null),
(121, 'No sujetarse a vehículos en movimiento', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No sujetarse a vehículos en movimiento;', '61', 'IV', '', 13, 20, false, null),
(122, 'No rebasar a ningún vehículo de motor por el mismo carril, a excepción de aquellos que pertenezcan a Policía o Policía Vial en el cumplimiento de su trabajo', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No rebasar a ningún vehículo de motor por el mismo carril, a excepción de aquellos que pertenezcan a Policía o Policía Vial en el cumplimiento de su trabajo;', '61', 'V', '', 10, 15, false, null),
(123, 'Queda estrictamente prohibido circular o estacionarse en carriles exclusivos para el transporte confinado y cualquier tipo de vehículo de emergencia. Asimismo, queda…', 'Queda estrictamente prohibido circular o estacionarse en carriles exclusivos para el transporte confinado y cualquier tipo de vehículo de emergencia. Asimismo, queda estrictamente prohibido circular por los carriles exclusivos para vehículo compartido, excepto los vehículos de uso particular para el traslado de personas que acaten los programas municipales de vehículo compartido y cualquier tipo de vehículo de emergencia.', '62', '', '', 10, 30, false, null),
(124, 'Cuando un vehículo esté indebidamente estacionado, cause interrupción a la circulación u obstruya la visibilidad de señales o dispositivos de tránsito, será retirado con grúa y…', 'Cuando un vehículo esté indebidamente estacionado, cause interrupción a la circulación u obstruya la visibilidad de señales o dispositivos de tránsito, será retirado con grúa y se depositará en el lote autorizado, si la interrupción de la circulación es intencional, se hará acreedor a una sanción sin derecho a descuento ni cancelación. Los gastos de acarreo y pensión serán por cuenta del infractor.', '63', '', '', 25, 35, false, null),
(125, 'Linternas, luces o reflejantes, también de color rojo. Estos dispositivos deben colocarse a 10-diez metros y 50-cincuenta metros hacia cada lado de donde se aproximen…', 'Cuando por circunstancias ajenas al conductor, el vehículo se encuentre sobre un carril de circulación y le sea imposible el movimiento del vehículo, se deberán de colocar inmediatamente los siguientes dispositivos: DE DÍA: Dos banderolas de color rojo de tamaño no menor a 50-cincuenta centímetros por lado, o reflejantes del mismo color; DE NOCHE: Linternas, luces o reflejantes, también de color rojo. Estos dispositivos deben colocarse a 10-diez metros y 50-cincuenta metros hacia cada lado de donde se aproximen vehículos, de tal forma que sean visibles desde una distancia de 100-cien metros.', '65', 'I y II', '', 10, 20, false, null),
(126, 'Queda prohibido separar lugares de estacionamiento si el lugar no está autorizado como exclusivo. El personal de la Secretaría con el auxilio de otras dependencias en caso de…', 'Queda prohibido separar lugares de estacionamiento si el lugar no está autorizado como exclusivo. El personal de la Secretaría con el auxilio de otras dependencias en caso de ser necesario, deberá retirar cualquier dispositivo utilizado con el propósito anterior.', '75', '', '', 10, 15, false, null),
(127, 'Queda prohibido el estacionamiento en áreas habitacionales y vía pública a aquellos vehículos o combinación de éstos con longitud mayor a 6.50 seis metros con cincuenta…', 'Queda prohibido el estacionamiento en áreas habitacionales y vía pública a aquellos vehículos o combinación de éstos con longitud mayor a 6.50 seis metros con cincuenta centímetros, a menos que estén realizando maniobras de carga y descarga o que se cuente con permiso especial expedido por la autoridad municipal quien podrá cancelarlo cuando se cause alguna afectación.', '76', '', '', 20, 30, false, null),
(128, 'Queda prohibido el estacionamiento en la vía pública de remolques y semirremolques, si no están unidos o acoplados a los vehículos que los estiran', 'Queda prohibido el estacionamiento en la vía pública de remolques y semirremolques, si no están unidos o acoplados a los vehículos que los estiran.', '77', '', '', 15, 20, false, null),
(129, 'Las personas físicas o morales de cualquier tipo que posean flotillas de vehículos deben tener un área destinada para estacionarlos sin afectar a sus vecinos. Por lo tanto, no…', 'Las personas físicas o morales de cualquier tipo que posean flotillas de vehículos deben tener un área destinada para estacionarlos sin afectar a sus vecinos. Por lo tanto, no podrán estacionar sus vehículos frente a domicilios contiguos a su domicilio social o centro de operaciones.', '79', '', '', 30, 50, false, null),
(130, 'Sobre banquetas, isletas, camellones o áreas diseñadas para separación de carriles, rotondas, zonas peatonales o diseñados para uso exclusivo de peatones, sobre parques…', 'Se prohíbe estacionar vehículos: Sobre banquetas, isletas, camellones o áreas diseñadas para separación de carriles, rotondas, zonas peatonales o diseñados para uso exclusivo de peatones, sobre parques públicos y al fondo de calles sin salida;', '80', 'I', '', 10, 20, false, null),
(131, 'Dentro de intersecciones y en cualquier área diseñada solamente para la circulación de vehículos', 'Se prohíbe estacionar vehículos: Dentro de intersecciones y en cualquier área diseñada solamente para la circulación de vehículos;', '80', 'II', '', 10, 15, false, null),
(132, 'Frente a hidrantes, rampas de carga y descarga o de acceso para personas con discapacidad o cocheras', 'Se prohíbe estacionar vehículos: Frente a hidrantes, rampas de carga y descarga o de acceso para personas con discapacidad o cocheras;', '80', 'VII', '', 30, 50, true, null),
(133, 'En donde lo prohíba una señal o Policía Vial, o en lugares exclusivos, sin permiso del titular', 'Se prohíbe estacionar vehículos: En donde lo prohíba una señal o Policía Vial, o en lugares exclusivos, sin permiso del titular;', '80', 'XIV', '', 15, 20, false, null),
(134, 'En cajones de estacionamiento para uso exclusivo de personas con discapacidad, a menos que se trate de un vehículo que esté debidamente identificado y que cuente con el permiso…', 'Se prohíbe estacionar vehículos: En cajones de estacionamiento para uso exclusivo de personas con discapacidad, a menos que se trate de un vehículo que esté debidamente identificado y que cuente con el permiso vigente y que transporte a la persona con discapacidad;', '80', 'XVIII', '', 30, 50, true, null),
(135, 'En cajones de estacionamiento donde existan estacionómetros instalados por la autoridad correspondiente, sin que se cubra el monto respectivo para utilizarlo', 'Se prohíbe estacionar vehículos: En cajones de estacionamiento donde existan estacionómetros instalados por la autoridad correspondiente, sin que se cubra el monto respectivo para utilizarlo;', '80', 'XIX', '', 1, 2, false, null),
(136, 'Estacionarse en lugar prohibido (esquinas, cruces peatonales, guarniciones pintadas, etc.)', 'Se prohíbe estacionar vehículos: En las esquinas u ochavos; A una distancia menor a un metro de las zonas de cruce de peatones, pintadas o imaginarias; A una distancia menor a un metro o mayor de 1.50- un metro con cincuenta centímetros del límite de propiedad cuando no haya banqueta; En un área comprendida desde 50-cincuenta metros antes y hasta 50-cincuenta metros después de puentes, túneles, vados, lomas, pasos a desnivel para vehículos, curvas y en cualquier otro lugar donde la visibilidad del vehículo estacionado no sea posible desde 100-cien metros; En la banqueta derecha, en las calles menores a 7-siete metros de ancho y cuya circulación sea de un solo sentido; En carriles principales cuando haya carriles secundarios; En zonas de carga y descarga sin estar realizando estas maniobras; A menos de 10-diez metros a cada lado de una señal de parada obligatoria para camiones de pasajeros, debiendo dejar un espacio mínimo de 10-diez metros; A menos de 5-cinco metros o sobre vías de ferrocarril; En cualquier forma que obstruya a los conductores la visibilidad de semáforos, señales de ALTO y de CEDA EL PASO, o cualquier otra señal de vialidad; En calles con amplitud menor a 5-cinco metros, a excepción de motocicletas, bicicletas y Vehículos de Micromovilidad; A un lado de rotondas, camellones o isletas; En línea con la banqueta en donde el estacionamiento se haga en forma diagonal o viceversa; En las guarniciones o cordones donde exista pintura color amarillo, rojo o azul en una o ambas caras; igualmente se prohíbe estacionar vehículos en las esquinas, aunque no exista señalamiento de no estacionarse, debiéndose respetar una distancia en ellas de 5-cinco metros lineales en ambos sentidos de las calles convergentes; y Estacionarse arriba de guías táctiles, pues obstaculizarían la movilidad de las personas con discapacidad visual.', '80', 'III, IV, V, VI, VIII, IX, X, XI, XII, XIII, XV, XVI, XVII, XX y XXI', '', 10, 20, false, 'Estacionamiento prohibido'),
(137, 'Los conductores de unidades de transporte escolar están obligados a encender sus luces especiales cuando se detengan para el ascenso y/o descenso de escolares y no deberán…', 'Los conductores de unidades de transporte escolar están obligados a encender sus luces especiales cuando se detengan para el ascenso y/o descenso de escolares y no deberán hacerlo en ninguna otra circunstancia.', '81', 'segundo párrafo', '', 15, 20, false, null),
(138, 'Faltas diversas por conductores del servicio público del transporte', 'Los pasajeros y ocupantes de vehículos, según el caso, deberán cumplir con lo siguiente: Usar el cinturón de seguridad; Viajar debidamente sentados en el lugar que les corresponda; Descender siempre por el lado de la banqueta o acotamiento; Los pasajeros del Servicio Local o Federal deben tener para los demás pasajeros y éstos para el operador una conducta de respeto, absteniéndose de realizar cualquier acto que ocasione molestias. Ningún pasajero puede hacer uso de aparatos reproductores de sonido a menos que use audífonos; y, Usar debidamente casco protector al viajar en motocicleta. (faltas diversas por conductores del servicio público del transporte).', '83', '', '', 20, 30, false, null),
(139, 'Faltas diversas cometidas por pasajeros y ocupantes de vehículos', 'Los pasajeros y ocupantes de vehículos, según el caso, deberán cumplir con lo siguiente: Usar el cinturón de seguridad; Viajar debidamente sentados en el lugar que les corresponda; Descender siempre por el lado de la banqueta o acotamiento; Los pasajeros del Servicio Local o Federal deben tener para los demás pasajeros y éstos para el operador una conducta de respeto, absteniéndose de realizar cualquier acto que ocasione molestias. Ningún pasajero puede hacer uso de aparatos reproductores de sonido a menos que use audífonos; y, Usar debidamente casco protector al viajar en motocicleta. (faltas diversas cometidas por pasajeros y ocupantes de vehículos).', '83', '', '', 20, 30, false, null),
(140, 'Faltas diversas cometidas por pasajeros y ocupantes de vehículos', 'Los pasajeros y ocupantes de vehículos, tienen prohibido lo siguiente: Ingerir bebidas alcohólicas en vehículos; Sacar del vehículo parte de su cuerpo u objetos; Arrojar basura u objetos a la vía pública; Abrir las puertas de vehículos en movimiento; Abrir sin precaución las puertas de vehículos estacionados hacia el lado de la circulación; Descender de vehículos en movimiento; Sujetarse del conductor o distraerlo; Operar los dispositivos de control del vehículo; Interferir en las funciones de los Policías Viales; y, Viajar en lugares destinados para carga o fuera del vehículo. El propietario del vehículo será el responsable solidario de las infracciones en que incurran los ocupantes. (faltas diversas cometidas por pasajeros y ocupantes de vehículos).', '84', '', '', 20, 30, false, null),
(141, 'Interferir en las funciones de los Policías o Policías Viales', 'Los pasajeros y ocupantes de vehículos, tienen prohibido lo siguiente: Interferir en las funciones de los Policías o Policías Viales', '84', 'IX', '', 5, 10, false, null),
(142, 'Las avenidas sobre las calles; La calle o avenida que tenga mayor cantidad de carriles de circulación; En intersecciones en forma de “T”, la que atraviese sobre la que…', 'En cruceros donde converjan dos o más avenidas, calles o carreteras, la prioridad de paso se determinará como sigue: En las esquinas o lugares donde haya señal gráfica de ALTO, los conductores deberán detener completamente sus vehículos. Esto es, antes de las zonas de peatones marcadas o a seis metros antes de la esquina en caso de que no estén marcadas; antes de iniciar la marcha de sus vehículos, los conductores deberán ceder el paso a los peatones que estén cruzando o hayan iniciado el cruce de una calle o avenida. Posteriormente, sin invadir el carril de circulación de la calle transversal, deberán cerciorarse de que no se aproxima ningún vehículo con el que se pueda ocasionar algún hecho de tránsito y hasta entonces iniciarán la marcha, evitando detenerse dentro de la intersección; Cuando todas las calles o carreteras convergentes en un crucero tengan señal de ALTO, la prioridad de paso será como sigue: Todos los vehículos deben hacer ALTO al llegar al cruce, el derecho de paso lo tiene el primero en llegar. Si solo uno hace ALTO y otro(s) no, el derecho de paso es de quien haya hecho ALTO. En las esquinas o lugares donde exista señal gráfica de CEDA EL PASO, los conductores podrán entrar a la intersección si por la calle transversal no se aproxima ningún vehículo que constituya peligro de hecho de tránsito; en caso contrario deberán cederle el paso; En cruceros o intersecciones donde no existan señales gráficas de ALTO o CEDA EL PASO, no haya semáforos funcionando normalmente y no se encuentre un Policía Vial dirigiendo la circulación; tendrán prioridad de paso: Las avenidas sobre las calles; La calle o avenida que tenga mayor cantidad de carriles de circulación; En intersecciones en forma de “T”, la que atraviese sobre la que entronca; La calle pavimentada sobre la no-pavimentada; y En las rotondas donde la circulación no esté controlada por señales o semáforos, los conductores que vayan a incorporarse a la misma deberán ceder el paso a los vehículos que ya se encuentren en ella. Al no presentarse las condiciones marcadas en los incisos anteriores, al conductor de un vehículo al que se le presente otro entrando a un crucero o aproximándose al suyo sobre su lado derecho, deberá cederle el paso.', '88', '', '', 10, 15, false, null),
(143, 'En las esquinas o lugares donde haya señal gráfica de ALTO, los conductores deberán detener completamente sus vehículos. Esto es, antes de las zonas de peatones marcadas o a…', 'En cruceros donde converjan dos o más avenidas, calles o carreteras, la prioridad de paso se determinará como sigue: En las esquinas o lugares donde haya señal gráfica de ALTO, los conductores deberán detener completamente sus vehículos. Esto es, antes de las zonas de peatones marcadas o a seis metros antes de la esquina en caso de que no estén marcadas; antes de iniciar la marcha de sus vehículos, los conductores deberán ceder el paso a los peatones que estén cruzando o hayan iniciado el cruce de una calle o avenida. Posteriormente, sin invadir el carril de circulación de la calle transversal, deberán cerciorarse de que no se aproxima ningún vehículo con el que se pueda ocasionar algún hecho de tránsito y hasta entonces iniciarán la marcha, evitando detenerse dentro de la intersección;', '88', 'I', '', 12, 15, false, null),
(144, 'Los vehículos de emergencia que hagan uso simultáneo de su sirena y torretas de luz roja, azul, blanca o ámbar, tendrán derecho de paso y movimiento sobre los demás vehículos…', 'Los vehículos de emergencia que hagan uso simultáneo de su sirena y torretas de luz roja, azul, blanca o ámbar, tendrán derecho de paso y movimiento sobre los demás vehículos los cuales deberán extremar precauciones. Se exceptúan los que circulen sobre rieles sin tener la obligación de respetar la preferencia o prioridad de paso en los cruceros o intersecciones. Los conductores de los demás vehículos deberán cederles el paso y auxiliarles en el libre movimiento. En el caso de un hecho de tránsito entre 2-dos o más vehículos de emergencia, haciendo uso de sirena y torretas de luz roja, azul, blanca o ámbar, se aplicará este Reglamento en forma normal.', '90', '', '', 15, 20, false, null),
(145, 'Los conductores de vehículos que inicien la marcha desde un carril o posición de estacionamiento, deberán ceder el paso a los vehículos en movimiento. Los que se encuentren…', 'Los conductores de vehículos que inicien la marcha desde un carril o posición de estacionamiento, deberán ceder el paso a los vehículos en movimiento. Los que se encuentren detenidos sobre un carril de circulación, antes de iniciar la marcha deberán ceder el paso a todo vehículo que haya iniciado alguna maniobra de rebase o vuelta sobre ellos o que haya iniciado el cruce de la calle transversal.', '91', '', '', 10, 15, false, null),
(146, 'Rebasar en lugares permitidos; Dar vuelta a la izquierda o en “U” en lugares permitidos; y Cuando el carril derecho, se encuentre parcial o totalmente obstruido. En cualquiera…', 'La circulación en calles o avenidas de doble circulación deberá hacerse como sigue: Cuando haya sólo un carril para cada circulación opuesta, la circulación deberá hacerse por el carril derecho, pudiendo usarse el carril opuesto si éste está libre, para: Rebasar en lugares permitidos; Dar vuelta a la izquierda o en “U” en lugares permitidos; y Cuando el carril derecho, se encuentre parcial o totalmente obstruido. En cualquiera de los 3-tres casos mencionados, se deberá ceder el paso a los vehículos que circulen acorde al sentido de circulación que se invade;', '92', 'I', '', 15, 20, false, null),
(147, 'Los camiones o autobuses de pasajeros y los vehículos de transporte de carga pesada, deberán hacerlo siempre por el carril de la derecha, a menos que vayan a dar vuelta a la…', 'La circulación en calles o avenidas de doble circulación deberá hacerse como sigue: Los camiones o autobuses de pasajeros y los vehículos de transporte de carga pesada, deberán hacerlo siempre por el carril de la derecha, a menos que vayan a dar vuelta a la izquierda o a rebasar;', '92', 'III', '', 30, 50, false, null),
(148, 'En las avenidas que cuenten con carril central neutro, este deberá de utilizarse para dar vuelta hacia la izquierda y no entorpecer los carriles normales de circulación', 'La circulación en calles o avenidas de doble circulación deberá hacerse como sigue: En las avenidas que cuenten con carril central neutro, este deberá de utilizarse para dar vuelta hacia la izquierda y no entorpecer los carriles normales de circulación.', '92', 'IV', '', 10, 15, false, null),
(149, 'Cerciorarse antes de iniciar la maniobra de que ningún vehículo que le siga haya iniciado previamente la misma maniobra de rebase', 'En las maniobras de rebase, los conductores deberán acatar lo siguiente: El conductor que va a rebasar debe: Cerciorarse antes de iniciar la maniobra de que ningún vehículo que le siga haya iniciado previamente la misma maniobra de rebase;', '94', 'I', 'b', 10, 15, false, null),
(150, 'Cerciorarse que el carril de circulación opuesta se encuentra libre de vehículos y obstáculos, en una longitud suficiente que permita realizar la maniobra de rebase sin peligro…', 'En las maniobras de rebase, los conductores deberán acatar lo siguiente: El conductor que va a rebasar debe: Cerciorarse que el carril de circulación opuesta se encuentra libre de vehículos y obstáculos, en una longitud suficiente que permita realizar la maniobra de rebase sin peligro y sin impedir la marcha normal de vehículos que circulen en sentido opuesto;', '94', 'I', 'c', 15, 20, false, null),
(151, 'Anunciar la maniobra de rebase con luces direccionales y en caso necesario con claxon. Por la noche, deberá hacerlo además con cambio de luces', 'En las maniobras de rebase, los conductores deberán acatar lo siguiente: El conductor que va a rebasar debe: Anunciar la maniobra de rebase con luces direccionales y en caso necesario con claxon. Por la noche, deberá hacerlo además con cambio de luces;', '94', 'I', 'd', 10, 15, false, null),
(152, 'Curvas horizontales y verticales, vados, túneles, pasos a desnivel, puentes, intersecciones o cruceros, vías de ferrocarril, en zonas escolares, cuando haya una línea central…', 'Se prohíbe rebasar de las siguientes formas: Por el carril de circulación en: curvas horizontales y verticales, vados, túneles, pasos a desnivel, puentes, intersecciones o cruceros, vías de ferrocarril, en zonas escolares, cuando haya una línea central continua en el pavimento y en todo lugar donde la visibilidad esté obstruida o limitada; Esta prohibición tendrá efecto desde 50-cincuenta metros antes de los lugares mencionados. Cuando en el pavimento existan simultáneamente una línea central continua y otra discontinua, la prohibición de rebasar será para aquellos vehículos que circulen sobre el carril donde esté la línea continua;', '95', 'I', '', 15, 20, false, null),
(153, 'Por el acotamiento', 'Se prohíbe rebasar de las siguientes formas: Por el acotamiento;', '95', 'II', '', 15, 20, false, null),
(154, 'Por el lado derecho en calles o avenidas de doble circulación que tengan solamente un carril para cada sentido de circulación', 'Se prohíbe rebasar de las siguientes formas: Por el lado derecho en calles o avenidas de doble circulación que tengan solamente un carril para cada sentido de circulación;', '95', 'III', '', 10, 15, false, null),
(155, 'A los vehículos que se encuentran detenidos cediendo el paso a peatones', 'Se prohíbe rebasar de las siguientes formas: A los vehículos que se encuentran detenidos cediendo el paso a peatones;', '95', 'V', '', 15, 20, false, null),
(156, 'Por el carril central neutro en las avenidas que cuenten con éste', 'Se prohíbe rebasar de las siguientes formas: Por el carril central neutro en las avenidas que cuenten con éste.', '95', 'IX', '', 10, 15, false, null),
(157, 'Señalar la maniobra con anticipación mediante el uso de las luces direccionales o con la mano', 'Los cambios de carril se deberán efectuar de la siguiente manera: Señalar la maniobra con anticipación mediante el uso de las luces direccionales o con la mano;', '97', 'I', '', 5, 10, false, null),
(158, 'En todos los casos el cambio de carril se hará de uno a la vez, transitando por cada uno una distancia considerable antes de pasar al siguiente, nunca se deberá hacer en forma…', 'Los cambios de carril se deberán efectuar de la siguiente manera: En todos los casos el cambio de carril se hará de uno a la vez, transitando por cada uno una distancia considerable antes de pasar al siguiente, nunca se deberá hacer en forma intempestiva;', '97', 'III', '', 5, 10, false, null),
(159, 'Tomar su carril correspondiente y señalar la maniobra mediante luces direccionales o con la mano desde una distancia de 50-cincuenta metros antes del lugar donde se vaya a…', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Tomar su carril correspondiente y señalar la maniobra mediante luces direccionales o con la mano desde una distancia de 50-cincuenta metros antes del lugar donde se vaya a voltear. Se permiten vueltas en más de una fila cuando en el lugar así se permita mediante señalamiento.', '98', 'I', 'a', 10, 15, false, null),
(160, 'Durante la maniobra, la velocidad será moderada', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Durante la maniobra, la velocidad será moderada.', '98', 'I', 'c', 10, 15, false, null),
(161, 'Durante la maniobra se deberá ceder el paso a los peatones que crucen la calle o avenida hacia donde se está efectuando la vuelta', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Durante la maniobra se deberá ceder el paso a los peatones que crucen la calle o avenida hacia donde se está efectuando la vuelta.', '98', 'I', 'd', 10, 15, false, null),
(162, 'Utilizar los carriles exclusivos canalizados o marcados para la realización de vueltas o cambio de dirección', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Utilizar los carriles exclusivos canalizados o marcados para la realización de vueltas o cambio de dirección.', '98', 'I', 'e', 10, 15, false, null),
(163, 'La aproximación se hará sobre el carril de la izquierda, lo más próximo posible a la banqueta, acotamiento o límite de arroyo de circulación; a menos que en el lugar existan…', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Tomar su carril correspondiente y señalar la maniobra mediante luces direccionales o con la mano desde una distancia de 50-cincuenta metros antes del lugar donde se vaya a voltear. Se permiten vueltas en más de una fila cuando en el lugar así se permita mediante señalamiento. Antes de efectuar la maniobra se deberá reducir gradualmente la velocidad. Durante la maniobra, la velocidad será moderada. Durante la maniobra se deberá ceder el paso a los peatones que crucen la calle o avenida hacia donde se está efectuando la vuelta; y Utilizar los carriles exclusivos canalizados o marcados para la realización de vueltas o cambio de dirección. En todos los casos deberá hacerse alto total antes de la zona de peatones marcada, o 6-seis metros antes de la esquina en caso de que no esté marcada, cediendo el paso a los peatones que estén cruzando o inicien el cruce. Las vueltas a la izquierda de una calle de doble circulación a cochera, estacionamiento, o cualquier lugar fuera de crucero o intersección deberán realizarse de la siguiente manera: La aproximación al lugar se hará sobre el carril izquierdo de su sentido de circulación junto al camellón o línea central pintada o imaginaria divisora de carriles; y Antes de entrar al carril de circulación opuesto, deberán ceder el paso a los vehículos que circulen en sentido opuesto, y a los que circulando atrás de ellos los puedan venir rebasando. Las vueltas a la izquierda de una calle de una sola circulación a una calle de doble circulación deberán realizarse de la siguiente manera: La aproximación al crucero o intersección se deberá hacer por el carril de la izquierda, lo más próximo posible a la banqueta, acotamiento o límite de arroyo de circulación; y Al entrar a la calle transversal, deberán hacerlo a la derecha del centro de la misma, a menos que en el lugar existan señales para dar vuelta en más de una fila. Las vueltas a la izquierda en cruceros donde ambas calles sean de una sola circulación deberán realizarse de la siguiente manera: La aproximación se hará sobre el carril de la izquierda, lo más próximo posible a la banqueta, acotamiento o límite de arroyo de circulación; a menos que en el lugar existan señales para dar vuelta en más de una fila; y Al entrar a la calle transversal podrán hacerlo en cualquiera de sus carriles.', '98', 'I, IV, V y VI', '', 12, 15, false, null),
(164, 'El conductor que de vuelta en “U”, en cruceros donde la calle transversal es de doble circulación, además de ceder el paso a los vehículos que circulen en sentido contrario,…', 'El conductor que de vuelta en “U”, en cruceros donde la calle transversal es de doble circulación, además de ceder el paso a los vehículos que circulen en sentido contrario, debe ceder el paso a los vehículos que circulando por la calle transversal estén dando vuelta a la derecha.', '102', '', '', 10, 15, false, null),
(165, 'Vuelta en U a media cuadra', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: A media cuadra, se exceptúan los casos cuando haya carriles de retorno;', '103', 'I', '', 10, 15, false, 'Girar en U prohibido'),
(166, 'Vuelta en U en puentes, curvas, zonas escolares o vías de ferrocarril', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: En puentes, túneles, vados, pasos a desnivel, lomas, curvas horizontales y verticales, zonas escolares y vías de ferrocarril;', '103', 'II', '', 12, 15, false, null),
(167, 'En cualquier lugar en donde la maniobra no pueda ser realizada sin efectuar reversa', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: En cualquier lugar en donde la maniobra no pueda ser realizada sin efectuar reversa;', '103', 'IV', '', 10, 15, false, null),
(168, 'En sentido contrario al que tenga la calle transversal', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: En sentido contrario al que tenga la calle transversal;', '103', 'V', '', 10, 15, false, null),
(169, 'Se permite circular en reversa solamente para entrar o salir de cajones de estacionamiento o cocheras, siempre y cuando el espacio que se circule no sea mayor a la longitud del…', 'Se permite circular en reversa solamente para entrar o salir de cajones de estacionamiento o cocheras, siempre y cuando el espacio que se circule no sea mayor a la longitud del vehículo que lo realice y sin atravesar cruceros. En caso de que la circulación hacia delante esté obstruida totalmente, se permitirá circular en reversa el tramo necesario de acuerdo a las circunstancias.', '104', '', '', 15, 20, false, null),
(170, 'No ceder el paso al circular en reversa', 'Los conductores de vehículos que circulen en reversa deberán ceder el paso y permitir el libre movimiento a aquellos que circulan de frente, con excepción de cuando dos vehículos pretendan entrar simultáneamente a ocupar un cajón de estacionamiento en paralelo. En este caso, la preferencia de movimiento y entrada al cajón de estacionamiento, será del vehículo que circule en reversa. (no ceder el paso al circular en reversa).', '105', '', '', 5, 10, false, null),
(171, 'No ceder el paso a vehículo que entra de reversa a estacionamiento', 'Los conductores de vehículos que circulen en reversa deberán ceder el paso y permitir el libre movimiento a aquellos que circulan de frente, con excepción de cuando dos vehículos pretendan entrar simultáneamente a ocupar un cajón de estacionamiento en paralelo. En este caso, la preferencia de movimiento y entrada al cajón de estacionamiento, será del vehículo que circule en reversa. (no ceder el paso a vehículo que entra de reversa a estacionamiento).', '105', '', '', 10, 15, false, null),
(172, 'Los conductores de vehículos que circulen en pendientes descendentes demasiado pronunciadas, deberán usar freno de motor además de los frenos de servicio', 'Los conductores de vehículos que circulen en pendientes descendentes demasiado pronunciadas, deberán usar freno de motor además de los frenos de servicio.', '106', '', '', 5, 7, false, null),
(173, 'Para los vehículos con peso bruto menor de 3,500- tres mil quinientos kilogramos, la distancia será de 3-tres metros por cada 10-diez kilómetros por hora de velocidad; y Para…', 'El conductor de un vehículo debe conservar, respecto del que va adelante, la distancia de seguridad que le garantice su detención oportuna, tomando en cuenta la velocidad, el estado de las calles o avenidas, las condiciones climáticas y las del propio vehículo. Los conductores conservarán entre su vehículo y el que les antecede una distancia como sigue: Para los vehículos con peso bruto menor de 3,500- tres mil quinientos kilogramos, la distancia será de 3-tres metros por cada 10-diez kilómetros por hora de velocidad; y Para los vehículos con peso mayor al anterior, la distancia será igual que en la fracción anterior, si la velocidad es menor a 50-cincuenta kilómetros por hora. Si ésta es mayor, la distancia, deberá ser de 5-cinco metros por cada 10-diez kilómetros de velocidad. Cuando las condiciones sean adversas, que limiten la visibilidad o hagan difícil la conducción de vehículos, se deberán aumentar las distancias antes referidas, de acuerdo a las circunstancias.', '107', '', '', 10, 15, false, null),
(174, 'Los conductores de vehículos que entren o salgan de cocheras particulares, cajones o espacios de estacionamiento, estacionamientos públicos o privados, áreas privadas, parques…', 'Los conductores de vehículos que entren o salgan de cocheras particulares, cajones o espacios de estacionamiento, estacionamientos públicos o privados, áreas privadas, parques o cualquier lugar no destinado para circulación de vehículos deberán ceder el paso al desplazamiento de peatones y circulación de vehículos en movimiento, con excepción de cuando estos últimos circulen en reversa o en sentido contrario a la circulación.', '108', '', '', 10, 15, false, null),
(175, 'Circular con luces apagadas', 'Los conductores de todo tipo de vehículos en movimiento deberán encender las luces de circulación, las auxiliares y las especiales de acuerdo a lo previsto en el artículo 31, fracción III del presente Reglamento, requeridas de éstos a la puesta del sol. También deberán encenderlas cuando las circunstancias les obstruyan o limiten la visibilidad. (circular con luces apagadas).', '109', '', '', 5, 10, false, null),
(176, 'Circular sin luces delanteras y/o traseras', 'Los conductores de todo tipo de vehículos en movimiento deberán encender las luces de circulación, las auxiliares y las especiales de acuerdo a lo previsto en el artículo 31, fracción III del presente Reglamento, requeridas de éstos a la puesta del sol. También deberán encenderlas cuando las circunstancias les obstruyan o limiten la visibilidad. (circular sin luces delanteras y/o traseras).', '109', '', '', 15, 20, false, null),
(177, 'Los conductores deberán realizar el cambio de luz alta a baja a favor de los conductores de vehículos que se les aproximen en sentido opuesto. Así mismo éstos deberán…', 'Los conductores deberán realizar el cambio de luz alta a baja a favor de los conductores de vehículos que se les aproximen en sentido opuesto. Así mismo éstos deberán realizarlo cuando se siga a otro vehículo de tal forma que el uso de la luz alta pueda deslumbrar al conductor del vehículo de adelante.', '110', '', '', 5, 10, false, null),
(178, 'Queda prohibido el uso de luces direccionales o de emergencia en caso innecesario y hacer uso de las luces altas en zona urbana, cuando el área esté iluminada', 'Queda prohibido el uso de luces direccionales o de emergencia en caso innecesario y hacer uso de las luces altas en zona urbana, cuando el área esté iluminada.', '111', '', '', 5, 10, false, null),
(179, 'Alterar, destruir, derribar, cubrir, cambiar de posición o lugar las señales y/o dispositivos para el control de tránsito y vialidad', 'Queda prohibido en las vías públicas lo siguiente: Alterar, destruir, derribar, cubrir, cambiar de posición o lugar las señales y/o dispositivos para el control de tránsito y vialidad;', '113', 'I', '', 15, 20, false, null),
(180, 'Colocar señales o dispositivos de tránsito, tales como boyas, bordos, barreras, aplicar pintura en banquetas, calles o demás vías públicas; o separar de alguna forma espacios…', 'Queda prohibido en las vías públicas lo siguiente: Colocar señales o dispositivos de tránsito, tales como boyas, bordos, barreras, aplicar pintura en banquetas, calles o demás vías públicas; o separar de alguna forma espacios para estacionar vehículos sin la autorización de la autoridad municipal;', '113', 'II', '', 15, 25, false, null),
(181, 'Colocar anuncios de cualquier tipo cuya disposición de forma, color, luz o símbolos, se haga de tal forma que puedan confundirse con señales de tránsito y vialidad, u…', 'Queda prohibido en las vías públicas lo siguiente: Colocar anuncios de cualquier tipo cuya disposición de forma, color, luz o símbolos, se haga de tal forma que puedan confundirse con señales de tránsito y vialidad, u obstaculizar la visibilidad de los mismos; así como colocar espejos en inmuebles que provoquen reflejos en los conductores de los vehículos;', '113', 'III', '', 15, 25, false, null),
(182, 'Arrojar materiales en vía pública', 'Queda prohibido en las vías públicas lo siguiente: Instalar, colocar, arrojar o abandonar objetos, tirar basura, lanzar o esparcir botellas, vidrios, clavos, latas o cualquier material o sustancia que pueda ensuciar o causar daños a las vías públicas u obstaculizar el tránsito de peatones y vehículos o causar algún hecho de tránsito; (arrojar materiales en vía pública).', '113', 'V', '', 20, 50, false, null),
(183, 'Tirar basura o líquidos o colocar y abandonar objetos en la vía pública', 'Queda prohibido en las vías públicas lo siguiente: Instalar, colocar, arrojar o abandonar objetos, tirar basura, lanzar o esparcir botellas, vidrios, clavos, latas o cualquier material o sustancia que pueda ensuciar o causar daños a las vías públicas u obstaculizar el tránsito de peatones y vehículos o causar algún hecho de tránsito; (tirar basura o líquidos o colocar y abandonar objetos en la vía pública).', '113', 'V', '', 20, 50, false, null),
(184, 'Con una barrera metálica canalizadora de 3-tres tableros de 30-treinta centímetros de ancho por 122-ciento veintidós centímetros y 2-dos lámparas de celdas atornilladas en cada…', 'Queda prohibido en las vías públicas lo siguiente: Al abrir zanjas o efectuar trabajos en la vía pública sin la autorización de la autoridad municipal, se procederá a retirar de la vía pública de los trabajos abanderando el área y asegurar los vehículos, equipo o maquinaria para garantizar el pago de los daños ocasionados a la vía pública, así como cumplir con la obligación de que soliciten las autorizaciones correspondientes a la Dependencia municipal competente. Cuando por circunstancias especiales, la autoridad antes mencionada otorgue un permiso para depositar materiales, hacer zanjas o realizar trabajos en la vía pública, se deberá señalar el lugar en los términos que para este efecto establezca la autoridad municipal requiriendo que la empresa que realice trabajos en la vía pública presente proyecto relativo al señalamiento de protección de obra, el cual deberá ser autorizado y supervisado por la propia autoridad municipal, requiriendo cuando menos lo siguiente: DE DÍA: Con una barrera metálica canalizadora de tres tableros de 30-treinta centímetros de ancho por 122-ciento veintidós centímetros como mínimo a cada lado del obstáculo o zona de trabajo por donde se aproximen peatones, semovientes o vehículos. DE NOCHE: Con una barrera metálica canalizadora de 3-tres tableros de 30-treinta centímetros de ancho por 122-ciento veintidós centímetros y 2-dos lámparas de celdas atornilladas en cada extremo de la barrera. Estos dispositivos deberán estar visibles a una distancia de, por lo menos, 100-cien metros de donde se efectúen los trabajos y de ser necesario reforzar con trafitambos colocados a cada 5-cinco metros en el sentido del tránsito hasta completar la distancia de visibilidad.', '113', 'VI', '', 15, 30, false, null),
(185, 'Reparar o dar mantenimiento a vehículos, a menos que se trate de una evidente emergencia; esta disposición deberá ser respetada especialmente frente a los talleres de servicio…', 'Queda prohibido en las vías públicas lo siguiente: Reparar o dar mantenimiento a vehículos, a menos que se trate de una evidente emergencia; esta disposición deberá ser respetada especialmente frente a los talleres de servicio automotriz de cualquier clase;', '113', 'VII', '', 15, 20, false, null),
(186, 'Utilizar las vías públicas como lotes para venta de vehículos', 'Queda prohibido en las vías públicas lo siguiente: Utilizar las vías públicas como lotes para venta de vehículos;', '113', 'XI', '', 15, 20, false, null),
(187, 'El abastecer de gas butano a vehículos en la vía pública', 'Queda prohibido en las vías públicas lo siguiente: El abastecer de gas butano a vehículos en la vía pública;', '113', 'XIII', '', 100, 200, false, null),
(188, 'Utilizar el claxon de manera prolongada a un ciclista o peatón', 'Queda prohibido en las vías públicas lo siguiente: El hacer uso indebido del claxon; en zonas escolares, hospitales, parques, plazas públicas, iglesias y donde exista concentración de personas; (utilizar el claxon de manera prolongada a un ciclista o peatón).', '113', 'XIV', '', 2, 10, false, null),
(189, 'Hacer uso indebido del claxon', 'Queda prohibido en las vías públicas lo siguiente: El hacer uso indebido del claxon; en zonas escolares, hospitales, parques, plazas públicas, iglesias y donde exista concentración de personas; (hacer uso indebido del claxon).', '113', 'XIV', '', 3, 5, false, null),
(190, 'El abandonar vehículos en la vía pública', 'Queda prohibido en las vías públicas lo siguiente: El abandonar vehículos en la vía pública;', '113', 'XVII', '', 10, 15, false, null),
(191, 'Utilizar la vía pública como área de carga y descarga sin permiso de la autoridad correspondiente', 'Queda prohibido en las vías públicas lo siguiente: Utilizar la vía pública como área de carga y descarga sin permiso de la autoridad correspondiente.', '113', 'XVIII', '', 20, 30, false, null),
(192, 'Para la realización de desfiles, caravanas, manifestaciones, peregrinaciones o cualquier otro tipo de concentración humana de carácter político, religioso, sindical, deportivo,…', 'Para la realización de desfiles, caravanas, manifestaciones, peregrinaciones o cualquier otro tipo de concentración humana de carácter político, religioso, sindical, deportivo, recreativo, conmemorativo, con finalidad lícita los cuales pueden originar conflictos viales, será necesario que sus organizadores den aviso por escrito a la autoridad municipal, por lo menos con 10-diez días hábiles antes del inicio de su celebración, a fin de que oportunamente ésta adopte las medidas preventivas e indispensables a la preservación de la seguridad de los participantes y al mismo tiempo se eviten trastornos a la vialidad, haciendo todo lo posible por encontrar, de común acuerdo, la autoridad municipal y los organizadores el horario y la vía o espacio público más adecuados a la conservación de la tranquilidad vial, sin menoscabo de los derechos humanos reconocidos por la Constitución Política de los Estados Unidos Mexicanos. En caso de hacer uso de abanderamiento por parte de la autoridad municipal, el organizador deberá realizar el pago de derechos correspondientes.', '114', '', '', 15, 20, false, null),
(193, 'Conducir sin licencia', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. (conducir sin licencia).', '115', 'primer párrafo', '', 10, 15, false, 'Conducir sin licencia'),
(194, 'Conducir con licencia no acorde al vehículo o servicio que presta', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. La licencia debe contener lo siguiente: Nombre completo; Fotografía del conductor; Tipo de Conductor; Fecha de vigencia y número de licencia; y Otros elementos que determine la autoridad que emite la licencia (conducir con licencia no acorde al vehículo o servicio que presta).', '115', 'I, II, III, IV y V', '', 5, 10, false, null),
(195, 'Conducir con licencia vencida', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. La licencia debe contener lo siguiente: Nombre completo; Fecha de vigencia y número de licencia; (conducir con licencia vencida).', '115', 'I y IV', '', 10, 15, false, null),
(196, 'Proporcionar datos falsos en expedición de licencia', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. La licencia debe contener lo siguiente: Nombre completo; Fotografía del conductor; Tipo de Conductor; Fecha de vigencia y número de licencia; y Otros elementos que determine la autoridad que emite la licencia (proporcionar datos falsos en expedición de licencia).', '115', 'I, II, III, IV y V', '', 20, 30, false, null),
(197, 'No se permite a ninguna persona trabajar como chofer con licencia de conducir expedida en el extranjero, a menos que el vehículo que se conduzca sea del mismo país donde se…', 'No se permite a ninguna persona trabajar como chofer con licencia de conducir expedida en el extranjero, a menos que el vehículo que se conduzca sea del mismo país donde se expidió la licencia.', '116', '', '', 15, 20, false, null),
(198, 'Conducir con licencia no acorde al vehículo o servicio que presta', 'Los conductores se clasifican en: CHOFER DE VEHÍCULOS DE SERVICIO PÚBLICO FEDERAL: Este deberá tener licencia del tipo indicado en la Ley de Caminos, Puentes y Autotransporte Federal, según sea el tipo de vehículo, de pasajeros o de carga; CHOFER DE VEHÍCULOS DE SERVICIO PÚBLICO LOCAL: Conductor de vehículos de servicio público, particular o industrial de 10-diez o más pasajeros. Conductor de toda clase de vehículos automotores de 4-cuatro o 6-seis ruedas, de servicio público de carga; así mismo toda persona que preste servicio conduciendo vehículos y reciba un salario, aun cuando éstos sean de servicio particular; Estará facultado para conducir vehículos de servicio particular. AUTOMOVILISTA: Conductor de vehículos de servicio particular de pasajeros y vehículos medianos de carga entendiéndose estos últimos como los vehículos que tengan una capacidad de carga de hasta 3,500-tres mil quinientos kilogramos. MOTOCICLISTA: Los conductores de motocicletas; VEHÍCULOS DE TRACCIÓN ANIMAL: Los que conducen este tipo de vehículos; y CICLISTA: Conductores de bicicletas, Vehículos de Micromovilidad y triciclos. (conducir con licencia no acorde al vehículo o servicio que presta).', '119', '', '', 5, 10, false, null),
(199, 'Los conductores de vehículos de transporte escolar que se detengan en la vía pública para efectuar maniobras de ascenso o descenso, deberán poner en funcionamiento las luces…', 'Los conductores de vehículos de transporte escolar que se detengan en la vía pública para efectuar maniobras de ascenso o descenso, deberán poner en funcionamiento las luces intermitentes de advertencia del vehículo, además de las establecidas en el artículo 31, fracción III, numeral 2 del presente Reglamento.', '128', '', '', 15, 20, false, null),
(200, 'Es responsabilidad del conductor del vehículo de transporte escolar tomar las debidas precauciones para que se realicen las maniobras de ascenso y descenso de escolares de…', 'Es responsabilidad del conductor del vehículo de transporte escolar tomar las debidas precauciones para que se realicen las maniobras de ascenso y descenso de escolares de manera segura.', '129', '', '', 20, 30, false, null),
(201, 'Al alcanzar un vehículo de transporte escolar detenido para el ascenso y descenso de escolares, todo conductor detendrá su vehículo atrás del transporte escolar', 'Además de las obligaciones y prohibiciones que se establecen para los conductores en los artículos 56 y 58 de este mismo Reglamento, los conductores estarán obligados a: Al alcanzar un vehículo de transporte escolar detenido para el ascenso y descenso de escolares, todo conductor detendrá su vehículo atrás del transporte escolar.', '130', 'III', '', 15, 20, false, null),
(202, 'Cuando notoriamente el vehículo sea un riesgo para la seguridad de su propio conductor, peatones y demás conductores', 'Se impedirá la circulación de vehículos y se retirarán de la vía pública, y en su caso se remitirán para depósito mediante el servicio de grúa, al verificarse cualquiera de los siguientes supuestos: Cuando notoriamente el vehículo sea un riesgo para la seguridad de su propio conductor, peatones y demás conductores;', '144', 'V', '', 5, 15, false, null),
(203, 'No mover el vehículo en un hecho de tránsito, cuando el Policía o Policía Vial así lo indique', 'Se impedirá la circulación de vehículos y se retirarán de la vía pública, y en su caso se remitirán para depósito mediante el servicio de grúa, al verificarse cualquiera de los siguientes supuestos: No mover el vehículo en un hecho de tránsito, cuando el Policía o Policía Vial así lo indique;.', '144', 'XIV', '', 50, 100, true, null),
(204, 'Hacer base o parada en lugar no autorizado', 'Los vehículos destinados al servicio público de transporte, además de los casos a que se refiere el artículo anterior, serán impedidos de circular y remitidos al lote autorizado por las siguientes causas: (Hacer base o parada en lugar no autorizado).', '145', 'II', '', 20, 30, false, null),
(205, 'Circular fuera de itinerario los vehículos del servicio público de pasajeros', 'Los vehículos destinados al servicio público de transporte, además de los casos a que se refiere el artículo anterior, serán impedidos de circular y remitidos al lote autorizado por las siguientes causas Circular fuera del horario y/o rutas autorizadas; (circular fuera de itinerario los vehículos del servicio público de pasajeros).', '145', 'I', '', 30, 50, false, null),
(206, 'Ser responsable en un hecho de tránsito', 'Un hecho de tránsito, es consecuencia de la omisión o transgresión a una norma de circulación por un conductor derivado del movimiento de uno o más vehículos, los cuales pueden chocar entre sí o con personas, semovientes u objetos ocasionándose separada o conjuntamente lesiones, pérdida de la vida o daños materiales, y se clasifican en: ALCANCE. - Ocurre entre 2-dos vehículos que circulan uno delante de otro, en el mismo carril o con la misma trayectoria y el de atrás impacta al de adelante, ya sea que este último vaya en circulación o se detenga normal o repentinamente; CHOQUE DE CRUCERO. - Ocurre entre 2-dos o más vehículos provenientes de arroyos de circulación que convergen o se cruzan, invadiendo un vehículo parcial o totalmente el arroyo de circulación de otro; CHOQUE DE FRENTE. - Ocurre entre 2-dos o más vehículos provenientes de arroyos de circulación opuestos, los cuales chocan cuando uno de ellos invade (n) parcial o totalmente el carril, arroyo de circulación o trayectoria contraria; CHOQUE LATERAL. - Ocurre entre 2-dos o más vehículos cuyos conductores circulan en carriles o con trayectorias paralelas, en el mismo sentido chocando los vehículos entre sí, cuando uno de ellos invada parcial o totalmente el carril o trayectoria donde circula el otro; SALIDA DE LA SUPERFICIE DE RODAMIENTO. - Ocurre cuando un conductor pierde el control de su vehículo y se sale de la calle, avenida o carretera; ESTRELLAMIENTO. - Ocurre cuando un vehículo en movimiento en cualquier sentido choca con algo que se encuentra provisional o permanentemente estático; VOLCADURA. - Ocurre cuando un vehículo pierde completamente el contacto entre llantas y superficie de rodamiento originándose giros verticales o transversales; PROYECCIÓN. - Ocurre cuando un vehículo en movimiento choca con o pasa sobre alguien o algo o lo suelta y lo proyecta contra alguien o algo, la proyección puede ser de tal forma que lo proyectado caiga en el carril o trayectoria de otro vehículo y se origine otro hecho de tránsito; ATROPELLO. - Ocurre cuando un vehículo en movimiento impacta con una persona. La persona puede estar estática o en movimiento ya sea caminando, corriendo o montando en patines, patinetas, o cualquier juguete similar, o trasladándose asistiéndose de aparatos o de vehículos no regulados por este reglamento, esto en el caso de las personas con discapacidad; CAÍDA DE PERSONA. - Ocurre cuando una persona cae hacia fuera o dentro de un vehículo en movimiento; CHOQUE CON MÓVIL DE VEHÍCULO. - Ocurre cuando alguna parte de un vehículo en movimiento o estacionado es abierto, sale, desprende o cae de éste e impacta con algo estático o en movimiento. En esta clasificación se incluyen aquellos casos en los que se caiga o se desprenda algo y no forme parte del vehículo, también cuando un conductor o pasajero saca alguna parte de su cuerpo y se impacta con alguien o algo; y CHOQUES DIVERSOS. - En esta clasificación queda cualquier hecho de tránsito no especificado en los puntos anteriores. (ser responsable en un hecho de tránsito).', '147', '', '', 15, 20, true, null),
(207, 'No mover los vehículos de la posición dejada por el hecho de tránsito', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: No mover los vehículos de la posición dejada por el hecho de tránsito;', '150', 'I', '', 10, 15, false, null),
(208, 'Prestar o solicitar ayuda para lesionados', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Prestar o solicitar ayuda para lesionados;', '150', 'II', '', 15, 30, false, null),
(209, 'Dar aviso inmediato, o a través de terceros a la dependencia correspondiente', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar aviso inmediato, o a través de terceros a la dependencia correspondiente;', '150', 'IV', '', 10, 15, false, null),
(210, 'Proteger el lugar del hecho de tránsito, abanderando de acuerdo a lo establecido en el presente Reglamento', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Proteger el lugar del hecho de tránsito, abanderando de acuerdo a lo establecido en el presente Reglamento;', '150', 'V', '', 10, 20, false, null),
(211, 'No esperar intervención del Policía o Policía Vial en caso de hecho de tránsito', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Esperar en el lugar del hecho de tránsito la intervención del personal de la dependencia competente, a menos que el conductor resulte con lesiones que requieran atención médica inmediata, en cuyo caso deberá notificarles en forma inmediata su localización y esperarlos en el lugar en que le fue prestada la atención médica; (no esperar intervención del Policía o Policía Vial en caso de hecho de tránsito).', '150', 'VI', '', 10, 15, false, null),
(212, 'Huir en caso de hecho de transito', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Esperar en el lugar del hecho de tránsito la intervención del personal de la dependencia competente, a menos que el conductor resulte con lesiones que requieran atención médica inmediata, en cuyo caso deberá notificarles en forma inmediata su localización y esperarlos en el lugar en que le fue prestada la atención médica; (huir en caso de hecho de transito).', '150', 'VI', '', 50, 200, true, null),
(213, 'Dar al personal de la dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también…', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar al personal de la dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también someterse a examen médico cuando se le requiera.', '150', 'VII', '', 10, 15, false, null),
(214, 'Negarse a dar datos y/o a entregar la licencia de conducir y tarjeta de circulación al Policía o Policía Vial', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar al personal de la Dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también someterse a examen médico cuando se les requiera. (negarse a dar datos y/o a entregar la licencia de conducir y tarjeta de circulación al Policía o Policía Vial).', '150', 'VII', '', 10, 15, true, null),
(215, 'Proporcionar datos falsos al personal de transito', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar al personal de la Dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también someterse a examen médico cuando se les requiera. (Proporcionar datos falsos al personal de transito).', '150', 'VII', '', 20, 30, true, null),
(216, 'Es obligación de las instituciones médicas públicas o privadas y de profesionistas de la medicina, el dar aviso a la autoridad municipal y a las autoridades correspondientes de…', 'Es obligación de las instituciones médicas públicas o privadas y de profesionistas de la medicina, el dar aviso a la autoridad municipal y a las autoridades correspondientes de cualquier les ionado que reciban para su atención si las lesiones fueron causadas en hechos de tránsito; debiendo además', '155', '', '', 15, 20, false, null),
(217, 'Circular sin seguro de responsabilidad civil vigente', 'Todos los vehículos de motor que circulen dentro del Municipio deben estar asegurados por lo menos contra daños a terceros en sus bienes y/o personas con póliza vigente expedida por una compañía de seguros autorizada por la Comisión Nacional de Seguros y Fianzas.', '157', '', '', 20, 25, false, null),
(218, 'No respetar señales y dispositivos de tránsito', 'Es obligación de todo usuario de la vía pública y privada con acceso al público, respetar fielmente todo lo indicado mediante señales y dispositivos.', '160', '', '', 10, 15, false, null),
(219, 'Las que deben hacer los conductores para anunciar un cambio de movimiento o dirección de sus vehículos cuando no funcionen las luces de freno o las direccionales, o el vehículo…', 'Señales humanas: las que deben hacer los conductores para anunciar un cambio de movimiento o dirección de sus vehículos cuando no funcionen las luces de freno o las direccionales, o el vehículo no esté equipado con dichos dispositivos.', '161', 'I', 'b', 3, 5, false, null),
(220, 'Señales humanas (alto, vuelta a la derecha, vuelta a la izquierda, estacionarse). Queda prohibido hacer estas señales cuando no se vaya a efectuar el cambio de dirección o…', 'Señales humanas (alto, vuelta a la derecha, vuelta a la izquierda, estacionarse). Queda prohibido hacer estas señales cuando no se vaya a efectuar el cambio de dirección o movimiento indicado, o cualquier otra señal que pueda confundir a los demás usuarios.', '161', 'I', 'b1, b2, b3 y b4', 5, 10, false, null),
(221, 'No respetar señales restrictivas (ALTO, CEDA EL PASO y demás)', 'Para los efectos de este Reglamento las señales y dispositivos para el control y verificación del tránsito serán: SEÑALES GRÁFICAS VERTICALES. - Las que se encuentran en lámina o en cualquier otro material y se colocan en perfiles o postes, sobre el piso y en las paredes de casas, edificios, puentes o lugares similares. B) RESTRICTIVAS. - Son aquellas que tienen por objeto indicar limitaciones o prohibiciones que regulan la circulación. Dichas señales tendrán fondo de color blanco con símbolos, leyendas y ribete en colores negro y/o rojo; su forma es cuadrada o rectangular, con excepción de las señales de ALTO Y CEDA EL PASO. La presentación de la primera será en forma octagonal, con fondo de color rojo y las leyendas y ribete en color blanco. La segunda será presentada en forma triangular, debiendo colocarse sobre un vértice. Se utilizarán, el color blanco en el fondo, rojo en el ribete y negro en la leyenda.', '161', 'II', 'b', 15, 20, false, 'No respetar señal de alto'),
(222, 'No respetar indicaciones del semáforo', 'Cuando la circulación esté regulada por medio de semáforos, las indicaciones de éstos tendrán el significado siguiente: ALTO: d) LUZ ROJA FIJA Y SOLA. - Los conductores deberán detener sus vehículos antes de cruzar la zona de peatones pintada o imaginaria; precisando que la vuelta continua a la derecha está permitida con precaución, excepto cuando exista un señalamiento que expresamente lo prohíba, en cuyo caso deberá cederse en todo momento el paso a los peatones que estén cruzando y a los vehículos que transiten por la vía a la que se pretende incorporar. e) LUZ ROJA INTERMITENTE. - Los conductores deberán de detener sus vehículos y podrán continuar la marcha después de ceder el paso a los peatones y vehículos que se aproximen por la calle transversal. f) FLECHA ROJA. - Los conductores de vehículos que pretendan circular en el sentido que indica la flecha, deberán detenerse antes de la zona de peatones hasta que una flecha verde les indique seguir. Al no existir la flecha en luz roja y no estar iluminada la flecha en luz verde, se considerará alto al sentido de la circulación que indique la flecha.', '163', 'III', '', 15, 30, false, null),
(223, 'Conducir en estado de ebriedad (suspensión de licencia)', 'Suspensión de licencia de conducir (art. 186): conducir en estado de ebriedad completo, estado de ebriedad incompleto o evidente estado de ebriedad, y demás supuestos de la fracción correspondiente.', '186', '', '', 200, 600, true, null),
(224, 'Insultar, amenazar o agredir al personal de Policía o Policía Vial', 'Insultar, amenazar o agredir al personal de Policía o Policía Vial.', '192', 'IX', '', 50, 100, true, null)
  insert into public.pagos (infraccion_id, folio_inf, monto_original, descuento_pct, monto_final, metodo, cajero, notas)
