-- ═══════════════════════════════════════════════════════════════════
-- Fundamento legal de las infracciones
--
-- Catálogo con el TABULADOR DE INFRACCIONES del Reglamento de Movilidad,
-- Tránsito y Seguridad Vial de San Pedro Garza García, N.L. (art. 186,
-- fracción VI). Texto de la compilación del Estado de Nuevo León con la
-- última reforma publicada en el Periódico Oficial No. 22 del 11-feb-2026.
-- Cada entrada trae el texto de la disposición, artículo, fracción, inciso,
-- la sanción en cuotas (UMA) y si es grave según el art. 192.
--
-- * Cada infracción guarda el número de catálogo y una copia del
--   fundamento tal como se imprimió (si el catálogo cambia después, la
--   boleta emitida conserva su fundamento).
-- * El monto debe quedar dentro del rango del tabulador (cuotas × UMA).
-- * Las infracciones graves (art. 192) se pagan íntegras, sin descuento.
--
-- Correr después de cobros.sql. Es idempotente: no sobrescribe los cambios
-- que el administrador haga al catálogo.
-- ═══════════════════════════════════════════════════════════════════

alter table public.configuracion add column if not exists valor_uma numeric default 117.31;
alter table public.configuracion add column if not exists reglamento text
  default 'Reglamento de Movilidad, Tránsito y Seguridad Vial de San Pedro Garza García, Nuevo León';
alter table public.configuracion add column if not exists fundamento_general text
  default 'Artículos 16, 21 y 115, fracción III, inciso h), de la Constitución Política de los Estados Unidos Mexicanos; y artículo 186, fracción VI, del Reglamento de Movilidad, Tránsito y Seguridad Vial de San Pedro Garza García, Nuevo León';
update public.configuracion set valor_uma = coalesce(valor_uma, 117.31) where id = 1;

create table if not exists public.catalogo_infracciones (
  numero       integer primary key,          -- No. en el tabulador del reglamento
  descripcion  text not null,                -- etiqueta corta para elegir
  texto        text not null,                -- texto de la disposición normativa
  articulo     text not null,
  fraccion     text not null default '',
  inciso       text not null default '',
  cuotas_min   integer not null,
  cuotas_max   integer not null,
  grave        boolean not null default false,  -- art. 192: sin descuento
  tipo_rapido  text unique,                  -- tipo de la lista rápida de la app
  activo       boolean not null default true,
  check (cuotas_min > 0 and cuotas_min <= cuotas_max)
);

alter table public.infracciones add column if not exists catalogo_numero integer references public.catalogo_infracciones(numero);
alter table public.infracciones add column if not exists fundamento text default '';

-- ── Texto del fundamento: "Artículo 58, fracción II, del Reglamento ..." ──
create or replace function public.fundamento_de(p_numero integer)
returns text
language sql stable
set search_path = public
as $$
  select 'Artículo ' || c.articulo
    || case
         when c.fraccion = '' then ''
         when c.fraccion ilike '%párrafo%' or c.fraccion ilike 'anexo%' then ', ' || c.fraccion
         when c.fraccion ~ '(,| y )' then ', fracciones ' || c.fraccion
         else ', fracción ' || c.fraccion
       end
    || case
         when c.inciso = '' then ''
         when c.inciso ~ '(,| y )' then ', incisos ' || c.inciso
         else ', inciso ' || c.inciso || ')'
       end
    || ', del ' || coalesce(cfg.reglamento, 'Reglamento de Tránsito')
  from public.catalogo_infracciones c
  left join public.configuracion cfg on cfg.id = 1
  where c.numero = p_numero
$$;

on conflict (numero) do nothing;

-- ── Al registrar o cambiar la infracción: fundamento y rango del monto ──
create or replace function public.aplicar_fundamento()
returns trigger
language plpgsql security definer
set search_path = public
as $$
declare
  c public.catalogo_infracciones%rowtype;
  v_uma numeric;
begin
  if new.catalogo_numero is null or current_setting('transito.migrando', true) = '1' then return new; end if;
  select * into c from public.catalogo_infracciones where numero = new.catalogo_numero;
  if tg_op = 'INSERT' or new.catalogo_numero is distinct from old.catalogo_numero then
    if not c.activo then raise exception 'La infracción % del catálogo está desactivada', c.numero; end if;
    new.fundamento := public.fundamento_de(c.numero);
  end if;
  if tg_op = 'INSERT' or new.monto is distinct from old.monto or new.catalogo_numero is distinct from old.catalogo_numero then
    select valor_uma into v_uma from public.configuracion where id = 1;
    if v_uma is not null and (new.monto < floor(c.cuotas_min * v_uma) or new.monto > ceil(c.cuotas_max * v_uma)) then
      raise exception 'El monto debe estar entre $% y $% (% a % cuotas de $% UMA, % )',
        to_char(floor(c.cuotas_min * v_uma), 'FM999,999'), to_char(ceil(c.cuotas_max * v_uma), 'FM999,999'),
        c.cuotas_min, c.cuotas_max, v_uma, public.fundamento_de(c.numero);
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_aplicar_fundamento on public.infracciones;
create trigger trg_aplicar_fundamento before insert or update of catalogo_numero, monto on public.infracciones
  for each row execute function public.aplicar_fundamento();

-- Vincular las infracciones ya registradas con su entrada del catálogo (por
-- tipo). No se les agrega fundamento ni se valida su monto: se emitieron antes.
select set_config('transito.migrando', '1', false);
update public.infracciones i set catalogo_numero = c.numero
from public.catalogo_infracciones c
where i.catalogo_numero is null and c.tipo_rapido = i.tipo;
select set_config('transito.migrando', '', false);

-- ── Cobro: las graves no tienen descuento (art. 192) ──────
create or replace function public.registrar_pago(
  p_infraccion_id bigint, p_aplicar_descuento boolean, p_metodo text, p_notas text default '')
returns public.pagos
language plpgsql security definer
set search_path = public
as $$
declare
  v_inf public.infracciones%rowtype;
  v_cfg public.configuracion%rowtype;
  v_cajero text;
  v_desc numeric := 0;
  v_pago public.pagos%rowtype;
begin
  select nombre into v_cajero from public.usuarios where auth_id = auth.uid() and activo;
  if v_cajero is null then raise exception 'Sesión no válida'; end if;
  if p_metodo not in ('efectivo','tarjeta','transferencia') then raise exception 'Método de pago inválido'; end if;

  select * into v_inf from public.infracciones where id = p_infraccion_id for update;
  if not found then raise exception 'Infracción no encontrada'; end if;
  if v_inf.estado in ('pagada','cancelada') or exists (select 1 from public.pagos where infraccion_id = p_infraccion_id) then
    raise exception 'La infracción % ya está %', v_inf.folio, case when v_inf.estado = 'cancelada' then 'cancelada' else 'pagada' end;
  end if;

  select * into v_cfg from public.configuracion where id = 1;
  if p_aplicar_descuento then
    if exists (select 1 from public.catalogo_infracciones where numero = v_inf.catalogo_numero and grave) then
      raise exception 'Infracción grave: se paga íntegra, sin descuento (art. 192 del Reglamento)';
    end if;
    if now() - v_inf.fecha > make_interval(days => coalesce(v_cfg.dias_descuento, 15)) then
      raise exception 'El periodo de descuento (% días) ya terminó', coalesce(v_cfg.dias_descuento, 15);
    end if;
    v_desc := coalesce(v_cfg.descuento_pct, 0);
  end if;

  values (v_inf.id, v_inf.folio, v_inf.monto, v_desc, round(v_inf.monto * (1 - v_desc / 100.0)), p_metodo, v_cajero, coalesce(p_notas, ''))
  returning * into v_pago;

  update public.infracciones set estado = 'pagada' where id = v_inf.id;
  return v_pago;
end $$;
revoke all on function public.registrar_pago(bigint, boolean, text, text) from public, anon;
grant execute on function public.registrar_pago(bigint, boolean, text, text) to authenticated;

-- ── Portal ciudadano: fundamento y si aplica descuento ────
-- Función nueva (consulta_publica conserva su forma para versiones anteriores
-- de la página).
create or replace function public.consulta_ciudadana(p_q text, p_historial boolean default false)
returns table (id bigint, folio text, fecha timestamptz, placa text, infractor text, tipo text,
               monto integer, estado text, ubicacion text, obs text, fundamento text, grave boolean)
language sql stable security definer
set search_path = public
as $$
  select i.id, i.folio, i.fecha, i.placa, i.infractor, i.tipo, i.monto, i.estado, i.ubicacion, i.obs,
         coalesce(i.fundamento, ''), coalesce(c.grave, false)
  from public.infracciones i
  left join public.catalogo_infracciones c on c.numero = i.catalogo_numero
  where length(regexp_replace(upper(coalesce(p_q,'')), '[^A-Z0-9]', '', 'g')) >= 3
    and (regexp_replace(upper(i.placa), '[^A-Z0-9]', '', 'g') = regexp_replace(upper(p_q), '[^A-Z0-9]', '', 'g')
      or regexp_replace(upper(i.folio), '[^A-Z0-9]', '', 'g') = regexp_replace(upper(p_q), '[^A-Z0-9]', '', 'g'))
    and (p_historial or i.estado in ('pendiente','impugnada','vencida'))
  order by i.fecha desc
  limit 25
$$;
grant execute on function public.consulta_ciudadana(text, boolean) to anon, authenticated;

-- ── Acceso ────────────────────────────────────────────────
alter table public.catalogo_infracciones enable row level security;
drop policy if exists personal_select on public.catalogo_infracciones;
drop policy if exists admin_update    on public.catalogo_infracciones;
create policy personal_select on public.catalogo_infracciones for select to authenticated using (public.mi_rol() is not null);
create policy admin_update on public.catalogo_infracciones for update to authenticated
  using (public.mi_rol() = 'admin') with check (public.mi_rol() = 'admin');
